import { atom, read, update } from 'claude-code'
import type { EngineInterface, PluginOptions, Register, Timer } from 'claude-code'

import { configCommand, firstUse, LANGUAGE, loadConfig, nextExpiry, onLine, pick, resolve, type ConfigIO, type Lang, type Resolved, type Specs } from './config'
import { MERGE_OPS, applyActions, changesNote, distillPrompt, latestProgress, mergePrompt, parseActions } from './distill'
import type { Rejected } from './distill'
import { FILE_PREFIX, INDEX_CAP, INDEX_FILE, indexEntries, joinLive, listLines, listed, notesOf, readStore, renderMemory, renderRule, splitLive, storeOf, updateIndex, withActiveDay } from './notes'
import type { Gone, Notes, RepoStore } from './notes'
import { PROGRESS_FILE, progressForPrompt, renderProgress, withExclude } from './progress'
import { PROMOTE_DESCRIPTION, PROMOTE_MIN_COUNT, PROMOTE_SCHEMA, PROMOTE_TOOL, applyPlaced, markAsked, promoteItems, promoteReport, promoteText, readReport } from './promote'
import { lastAnchor, transcriptOf, userTextOf } from './transcript'
import type { Row } from './transcript'

const COMMAND = 'project-memory'
const TOOL = 'mcp__project-memory__mark_in_project'
const NOTES_MODEL = 'sonnet'
const DISTILL_MAX_TOKENS = 4000
const DISTILL_TIMEOUT_MS = 3 * 60_000
// Besides every N prompts: after idling, and at a /clear, once this many prompts are new.
const END_MIN_TURNS = 5

const pending = atom({ plugin: 'project-memory', key: 'pending' } as const, null)
const promoted = atom({ plugin: 'project-memory', key: 'promoted' } as const, false)
const onUntil = atom({ plugin: 'project-memory', key: 'onUntil' } as const, {})
const now = atom({ plugin: 'project-memory', key: 'now' } as const, 0)

// Redraws the time left of a feature switched on for a while.
const TICK_MS = 30_000

type Config = { isDistillOn: boolean; every: number; minTokens: number; idleMs: number; maxRate: number; isPromoteOn: boolean; lang: Lang }
type Last = { at: number; why: string; changes: string[]; rejected: Rejected; error?: string }
// An automatic distill left out because the account's usage was high: not a failure.
type Skipped = { at: number; why: string; kind: string; percent: number; max: number }
type Mark = { turn: number; anchor?: string }
// The conversation as it stood when a /clear ended it: the distill runs after the session moved on.
type Snapshot = { sid: string; turns: number; rows: readonly Row[] }

const clamp = (v: unknown, fallback: number, min: number, max: number) =>
  typeof v === 'number' && Number.isFinite(v) ? Math.min(max, Math.max(min, Math.round(v))) : fallback

export function configOf(options: Record<string, unknown>): Config {
  return {
    isDistillOn: options.distill === true,
    every: clamp(options.distill_every, 30, 5, 200),
    minTokens: clamp(options.min_context_k, 30, 0, 1000) * 1000,
    // 0: no distill on idling.
    idleMs: clamp(options.idle_minutes, 10, 0, 120) * 60_000,
    maxRate: clamp(options.max_rate_used, 80, 0, 100),
    isPromoteOn: options.promote !== false,
    lang: options.language === 'zh-TW' ? 'zh-TW' : 'en',
  }
}

const slash = (p: string) => p.replace(/\\/g, '/').replace(/\/+$/, '')
const dirOf = (p: string) => slash(p).replace(/\/[^/]*$/, '')
const encodeProject = (p: string) => slash(p).replace(/[^A-Za-z0-9]/g, '-')

// Local "YYYY-MM-DD HH:mm".
export function localStamp(ms: number) {
  const d = new Date(ms - new Date(ms).getTimezoneOffset() * 60_000)

  return d.toISOString().slice(0, 16).replace('T', ' ')
}

// The repository the notes belong to: the main working tree's root, so worktrees share them.
async function workspace($: EngineInterface): Promise<string> {
  return slash((await $.session.repo())?.root ?? (await $.session.root()))
}

// The built-in memory folder: where the context loaded MEMORY.md from, else where Claude Code keeps it.
// Asked once per repository: the breakdown is not free.
const dirs = new Map<string, string>()

async function memoryDir($: EngineInterface): Promise<string> {
  const root = await workspace($)
  const known = dirs.get(root)
  if (known !== undefined) return known
  const dir = await findMemoryDir($, root)
  dirs.set(root, dir)

  return dir
}

async function findMemoryDir($: EngineInterface, root: string): Promise<string> {
  try {
    const usage = await $.session.usage({ breakdown: 'summary' })
    const auto = usage.context.breakdown?.memoryFiles.find(f => f.type === 'AutoMem' && slash(f.path).endsWith(`/${INDEX_FILE}`))
    if (auto !== undefined) {
      return dirOf(auto.path)
    }
  } catch {
    // Fall back to the computed folder.
  }
  const custom = await $.env.get('CLAUDE_CONFIG_DIR')
  const home = custom ? slash(custom) : `${slash((await $.env.get('HOME')) ?? (await $.env.get('USERPROFILE')) ?? '')}/.claude`

  return `${home}/projects/${encodeProject(root)}/memory`
}

async function readText($: EngineInterface, path: string): Promise<string> {
  try {
    return await $.fs.read(path)
  } catch {
    return ''
  }
}

const repoKey = async ($: EngineInterface) => `repo:${await workspace($)}`
const lastKey = async ($: EngineInterface) => `last:${await workspace($)}`
const skipKey = async ($: EngineInterface) => `skipped:${await workspace($)}`
const today = async ($: EngineInterface) => localStamp(await $.clock.now()).slice(0, 10)

async function loadStore($: EngineInterface): Promise<RepoStore> {
  return readStore(await $.store.get(await repoKey($)))
}

// Counts the day toward staleness: a memory goes stale over days the repository was worked on.
let notedDay = ''

async function noteActiveDay($: EngineInterface): Promise<void> {
  const key = `${await workspace($)}|${await today($)}`
  if (key === notedDay) return
  const store = await loadStore($)
  const days = withActiveDay(store.activeDays, await today($))
  if (days !== undefined) await $.store.set(await repoKey($), { ...store, activeDays: days })
  notedDay = key
}

// This mod's files in the memory folder, by name.
async function ownFiles($: EngineInterface, dir: string): Promise<{ file: string; text: string }[]> {
  let entries: { name: string; kind: string }[] = []
  try {
    entries = await $.fs.list(dir)
  } catch {
    return []
  }
  const files: { file: string; text: string }[] = []
  for (const entry of entries) {
    if (entry.kind === 'file' && entry.name.startsWith(FILE_PREFIX) && entry.name.endsWith('.md')) {
      files.push({ file: entry.name, text: await readText($, `${dir}/${entry.name}`) })
    }
  }

  return files
}

// Each memory and rule file's refs no longer found: the file gone, or its anchor no longer in it.
// A file that cannot be read counts as found.
async function gonePaths($: EngineInterface, notes: Notes, root: string): Promise<Map<string, Gone[]>> {
  const gone = new Map<string, Gone[]>()
  const texts = new Map<string, Promise<string | undefined>>()
  const textOf = (path: string) => {
    if (!texts.has(path)) texts.set(path, $.fs.read(`${root}/${path}`).catch(() => undefined))

    return texts.get(path)!
  }
  for (const item of [...notes.memory, ...notes.rules]) {
    if (item.file === undefined || item.paths.length === 0) continue
    const missing: Gone[] = []
    for (const p of item.paths) {
      if (!(await $.fs.exists(`${root}/${p.path}`).catch(() => true))) {
        missing.push({ path: p.path })
        continue
      }
      if (p.anchor === undefined) continue
      const text = await textOf(p.path)
      if (text !== undefined && !text.includes(p.anchor)) missing.push(p)
    }
    if (missing.length > 0) gone.set(item.file, missing)
  }

  return gone
}

// Writes what changed: each changed file, files no longer in the notes deleted, this mod's lines of
// MEMORY.md, the store. The asks and active days are read again unless given: a prompt may have
// recorded one while the distill ran.
async function saveNotes($: EngineInterface, lang: Lang, dir: string, before: readonly { file: string; text: string }[], notes: Notes, asked?: RepoStore['asked']): Promise<void> {
  const old = new Map(before.map(f => [f.file, f.text]))
  const kept = new Set<string>()
  for (const m of notes.memory) {
    kept.add(m.file)
    const text = renderMemory(m, lang)
    if (old.get(m.file) !== text) await $.fs.write(`${dir}/${m.file}`, text)
  }
  for (const r of notes.rules) {
    if (r.file === undefined) continue
    kept.add(r.file)
    const text = renderRule(r, lang)
    if (old.get(r.file) !== text) await $.fs.write(`${dir}/${r.file}`, text)
  }
  for (const file of old.keys()) {
    if (!kept.has(file)) await $.process.run(['rm', '-f', `${dir}/${file}`], { timeoutMs: 5000 })
  }
  const store = await loadStore($)
  const indexPath = `${dir}/${INDEX_FILE}`
  const index = await readText($, indexPath)
  const next = updateIndex(index, indexEntries(notes, store.activeDays))
  if (next !== index) await $.fs.write(indexPath, next)
  await $.store.set(await repoKey($), storeOf(notes, asked ?? store.asked, store.activeDays))
}

// `.claude/progress.md` in the repository, kept out of git through `.git/info/exclude`.
async function saveProgress($: EngineInterface, root: string, text: string): Promise<void> {
  await $.fs.write(`${root}/${PROGRESS_FILE}`, text)
  const exclude = `${root}/.git/info/exclude`
  if ((await $.fs.stat(`${root}/.git`).catch(() => undefined))?.kind !== 'dir') return
  const added = withExclude(await readText($, exclude))
  if (added !== undefined) await $.fs.write(exclude, added)
}

async function ask($: EngineInterface, system: string, prompt: string) {
  return $.model.complete({ model: NOTES_MODEL, effort: 'low', maxTokens: DISTILL_MAX_TOKENS, timeoutMs: DISTILL_TIMEOUT_MS, system, prompt })
}

// Past the index cap: one more request that may only merge and invalidate. Its result, or the
// notes as they were when it fails (the index then keeps the most recently confirmed).
async function mergeOver(
  $: EngineInterface,
  lang: Lang,
  notes: Notes,
  activeDays: readonly string[],
  day: string,
  sid: string,
  taken: ReadonlySet<string>,
): Promise<{ notes: Notes; changes: string[] }> {
  const count = listed(notes, activeDays).length
  if (count <= INDEX_CAP) return { notes, changes: [] }
  const { live, dead } = splitLive(notes)
  const r = await ask($, mergePrompt(live, activeDays, count, INDEX_CAP, lang), 'Output ACTIONS as the system prompt instructs.')
  if (!r.isAnswered) {
    $.ui.log(`project-memory: merge failed: ${r.reason}`, { to: 'debug' })

    return { notes, changes: [] }
  }
  const { actions } = parseActions(r.text, live, '', MERGE_OPS, lang)
  const merged = applyActions(actions, live, day, sid, taken, lang)

  return { notes: joinLive(merged.notes, dead, day), changes: merged.changes.map(c => pick(lang, { en: `Merged: ${c}`, 'zh-TW': `合併：${c}` })) }
}

let running = false
// After a failed automatic distill, wait this many prompts before the next try, so an outage
// does not cost a request every turn.
const RETRY_TURNS = 5
let retryAt = 0

// Distills the conversation since the last distill into the memory folder and the progress file.
// snap: a conversation that already ended (/clear); otherwise the session's own. Returns what to
// tell the person.
async function distill($: EngineInterface, lang: Lang, why: string, snap?: Snapshot): Promise<string> {
  if (running) return pick(lang, { en: 'A distill is running; try again shortly.', 'zh-TW': '整理中，稍後再試。' })
  const sid = snap?.sid ?? (await $.session.id())
  const markKey = `distill:${sid}`
  const mark = (await $.store.get(markKey)) as Mark | undefined
  const turns = snap?.turns ?? (await $.session.turns())
  if (turns <= (mark?.turn ?? 0)) return pick(lang, { en: 'No new conversation since the last distill.', 'zh-TW': '上次整理後沒有新的對話。' })
  running = true
  const lk = await lastKey($)
  const started = await $.clock.now()
  const fail = async (error: string) => {
    $.ui.log(`project-memory: distill failed (${why}): ${error}`, { to: 'debug' })
    if (snap === undefined) retryAt = turns + RETRY_TURNS
    await $.store.set(lk, { at: started, why, changes: [], rejected: { count: 0, samples: [] }, error } satisfies Last)

    return pick(lang, { en: `Distill failed: ${error}`, 'zh-TW': `整理失敗：${error}` })
  }
  try {
    const rows = snap?.rows ?? ((await $.session.messages()) as readonly Row[])
    const transcript = transcriptOf(rows, mark?.anchor)
    const dir = await memoryDir($)
    const root = await workspace($)
    const files = await ownFiles($, dir)
    const store = await loadStore($)
    const { live, dead } = splitLive(notesOf(files, store))
    const day = localStamp(started).slice(0, 10)
    const r = await ask(
      $,
      distillPrompt(transcript.found ? mark?.anchor : undefined, live, store.activeDays, progressForPrompt(await readText($, `${root}/${PROGRESS_FILE}`)), await gonePaths($, live, root), lang),
      `=== TRANSCRIPT ===\n${transcript.text || '(no new conversation)'}\n=== END OF TRANSCRIPT ===\n\nOutput ACTIONS as the system prompt instructs.`,
    )
    if (!r.isAnswered) {
      return await fail(r.reason === 'api-error' ? `api-error ${r.status ?? ''} ${r.error}` : r.reason)
    }
    const { actions, rejected } = parseActions(r.text, live, userTextOf(rows), undefined, lang)
    const now = await $.clock.now()
    // Someone changed the files meanwhile: the numbers no longer match; distill the same stretch next time.
    const again = await ownFiles($, dir)
    if (again.length !== files.length || again.some((f, i) => f.file !== files[i]?.file || f.text !== files[i]?.text)) {
      return await fail(pick(lang, { en: 'the memory files were changed during the distill; the same stretch is distilled next time', 'zh-TW': '整理期間記憶檔被改過，下次重新整理同一段' }))
    }
    const taken = new Set((await $.fs.list(dir).catch(() => [])).map(entry => entry.name))
    const applied = applyActions(actions, live, day, sid, taken, lang)
    const merged = await mergeOver($, lang, joinLive(applied.notes, dead, day), store.activeDays, day, sid, taken)
    const changes = [...applied.changes, ...merged.changes]
    await saveNotes($, lang, dir, files, merged.notes)
    const progress = latestProgress(actions)
    if (progress !== undefined) await saveProgress($, root, renderProgress({ ...progress, session: sid, at: now }, localStamp(now), lang))
    const anchor = lastAnchor(rows)
    await $.store.set(markKey, { turn: turns, ...(anchor ? { anchor } : {}) } satisfies Mark)
    await $.store.set(lk, { at: now, why, changes, rejected } satisfies Last)
    $.ui.log(`project-memory: distill done (${why}): ${changes.length} change(s), ${rejected.count} line(s) dropped${progress ? ', progress updated' : ''}`, { to: 'debug' })
    if (changes.length > 0) {
      await update($, pending, p => ({ changes: [...(p?.changes ?? []), ...changes], dir }))
      $.ui.toast(pick(lang, { en: `project-memory: ${changes.length} change(s) to the memory (${dir})`, 'zh-TW': `project-memory：記憶有 ${changes.length} 項變動（${dir}）` }))
    }

    return statusLines(lang, changes, rejected, progress !== undefined, dir)
  } catch (error) {
    return await fail(String(error))
  } finally {
    running = false
  }
}

let expiry: Timer | undefined
let ticker: Timer | undefined

async function tick($: EngineInterface): Promise<void> {
  const at = await $.clock.now()
  await update($, now, () => at)
}

// Takes new settings: the idle timer and the band follow them, and the end of a feature switched
// on for a while reads them again.
async function settle($: EngineInterface, resolved: Resolved, options: PluginOptions, take: (config: Config) => void): Promise<void> {
  const config = configOf(resolved.values)
  take(config)
  if (!config.isDistillOn) {
    idle?.cancel()
    idle = undefined
  }
  await update($, onUntil, () => resolved.until)
  await tick($)
  const at = nextExpiry(resolved)
  const delay = at === undefined ? 0 : Math.max(0, at - (await $.clock.now()))
  // No await from here on: two settles at once must not leave a timer nobody can cancel.
  expiry?.cancel()
  ticker?.cancel()
  expiry = at === undefined ? undefined : $.clock.after(delay, () => void reload($, options, take).catch(() => undefined))
  ticker = at === undefined ? undefined : $.clock.every(TICK_MS, () => void tick($))
}

async function reload($: EngineInterface, options: PluginOptions, take: (config: Config) => void): Promise<void> {
  await settle($, await loadConfig(configIO($), COMMAND, SPECS, options), options, take)
}

// Idle long enough with enough new prompts: distill now, while the person is away.
let idle: Timer | undefined

async function onIdle($: EngineInterface, config: Config): Promise<void> {
  const { lang, idleMs } = config
  idle = undefined
  if (running) return
  const mark = (await $.store.get(`distill:${await $.session.id()}`)) as Mark | undefined
  const turns = await $.session.turns()
  if (turns - (mark?.turn ?? 0) < END_MIN_TURNS || turns < retryAt) return
  await autoDistill($, config, pick(lang, { en: `idle for ${idleMs / 60_000} minutes`, 'zh-TW': `閒置 ${idleMs / 60_000} 分鐘` }))
}

// The 5-hour or 7-day window used past max percent; none off a subscription or when usage is not known.
export function overRate(limits: readonly { kind: string; percentUsed: number }[] | undefined, max: number) {
  return limits?.find(l => (l.kind === 'five_hour' || l.kind === 'seven_day') && l.percentUsed > max)
}

const windowName = (lang: Lang, kind: string) =>
  kind === 'five_hour' ? pick(lang, { en: '5-hour', 'zh-TW': '5 小時' }) : kind === 'seven_day' ? pick(lang, { en: '7-day', 'zh-TW': '7 天' }) : kind

const skipText = (lang: Lang, s: Skipped) =>
  pick(lang, {
    en: `${s.why}: the ${windowName(lang, s.kind)} limit is ${s.percent}% used, over ${s.max}%`,
    'zh-TW': `${s.why}：${windowName(lang, s.kind)}額度已用 ${s.percent}%，超過 ${s.max}%`,
  })

// A distill this mod starts on its own: left out while the account's usage is high (a /clear's
// conversation is then dropped); the first one in a session says what it costs.
async function autoDistill($: EngineInterface, config: Config, why: string, snap?: Snapshot): Promise<string> {
  const lang = config.lang
  const over = overRate(await $.session.usage().then(u => u.rateLimits, () => undefined), config.maxRate)
  if (over !== undefined) {
    const skipped: Skipped = { at: await $.clock.now(), why, kind: over.kind, percent: over.percentUsed, max: config.maxRate }
    $.ui.log(`project-memory: automatic distill skipped (${why}): ${over.kind} ${over.percentUsed}% > ${config.maxRate}%`, { to: 'debug' })
    await $.store.set(await skipKey($), skipped)

    return skipText(lang, skipped)
  }
  if (await firstUse(configIO($), 'distill')) {
    $.ui.toast(
      pick(lang, {
        en: `${COMMAND}: automatic distilling now sends new conversation to Sonnet (${why}); turn off: /${COMMAND} off`,
        'zh-TW': `${COMMAND}：自動整理開始把新增的對話送給 Sonnet（${why}）；關閉：/${COMMAND} off`,
      }),
    )
  }

  return distill($, lang, why, snap)
}

function statusLines(lang: Lang, changes: readonly string[], rejected: Rejected, isProgress: boolean, dir: string) {
  return [
    changes.length > 0 ? pick(lang, { en: `${changes.length} change(s) to the memory (${dir}):`, 'zh-TW': `記憶有 ${changes.length} 項變動（${dir}）：` }) : pick(lang, { en: 'No change to the memory.', 'zh-TW': '記憶沒有變動。' }),
    ...changes.map(c => `- ${c}`),
    ...(isProgress ? [pick(lang, { en: `Updated ${PROGRESS_FILE}.`, 'zh-TW': `已更新 ${PROGRESS_FILE}。` })] : []),
    ...(rejected.count > 0
      ? [pick(lang, { en: `Dropped ${rejected.count} invalid output line(s):`, 'zh-TW': `丟棄 ${rejected.count} 行無效輸出：` }), ...rejected.samples.map(s => `- ${s}`)]
      : []),
  ].join('\n')
}

async function statusText($: EngineInterface, config: Config): Promise<string> {
  const lang = config.lang
  const last = (await $.store.get(await lastKey($))) as Last | undefined
  const skipped = (await $.store.get(await skipKey($))) as Skipped | undefined
  const mark = (await $.store.get(`distill:${await $.session.id()}`)) as Mark | undefined
  const since = (await $.session.turns()) - (mark?.turn ?? 0)
  const store = await loadStore($)
  const dir = await memoryDir($)
  const notes = notesOf(await ownFiles($, dir), store)
  const { live, dead } = splitLive(notes)

  const idleText = config.idleMs > 0 ? pick(lang, { en: `idle for ${config.idleMs / 60_000} minutes or `, 'zh-TW': `閒置 ${config.idleMs / 60_000} 分鐘或 `}) : ''
  const enabled = pick(lang, {
    en: `on (every ${config.every} messages with context over ${config.minTokens / 1000}k; ${idleText}${END_MIN_TURNS}+ messages at /clear; ${since} since the last)`,
    'zh-TW': `開（每 ${config.every} 則且 context ${config.minTokens / 1000}k 以上；${idleText}/clear 時有 ${END_MIN_TURNS} 則以上；距上次 ${since} 則）`,
  })
  const counts = pick(lang, {
    en: `${live.memory.length} memories, ${live.rules.filter(r => r.file !== undefined).length} rules, ${notes.procedures.length} procedures, ${dead.memory.length + dead.rules.length} invalidated; MEMORY.md lists ${Math.min(INDEX_CAP, listed(notes, store.activeDays).length)}/${INDEX_CAP} (${dir})`,
    'zh-TW': `記憶 ${live.memory.length} 條、規則 ${live.rules.filter(r => r.file !== undefined).length} 條、流程 ${notes.procedures.length} 個、失效 ${dead.memory.length + dead.rules.length} 條；MEMORY.md 列出 ${Math.min(INDEX_CAP, listed(notes, store.activeDays).length)}／${INDEX_CAP} 條（${dir}）`,
  })

  return [
    pick(lang, { en: `Automatic distill: ${config.isDistillOn ? enabled : 'off'}`, 'zh-TW': `自動整理：${config.isDistillOn ? enabled : '關'}` }),
    ...(config.isDistillOn
      ? [pick(lang, { en: `Skipped while the 5-hour or 7-day limit is over ${config.maxRate}% used`, 'zh-TW': `5 小時或 7 天額度用量超過 ${config.maxRate}% 時跳過` })]
      : []),
    counts,
    last === undefined
      ? pick(lang, { en: 'Not distilled yet.', 'zh-TW': '還沒整理過。' })
      : pick(lang, {
          en: `Last distill: ${localStamp(last.at)} (${last.why})${last.error ? ` failed: ${last.error}` : `, ${last.changes.length} change(s)`}`,
          'zh-TW': `上次整理：${localStamp(last.at)}（${last.why}）${last.error ? `失敗：${last.error}` : `，${last.changes.length} 項變動`}`,
        }),
    ...(skipped !== undefined && (last === undefined || skipped.at > last.at)
      ? [pick(lang, { en: `Last skipped: ${localStamp(skipped.at)} (${skipText(lang, skipped)})`, 'zh-TW': `最近一次跳過：${localStamp(skipped.at)}（${skipText(lang, skipped)}）` })]
      : []),
  ].join('\n')
}

export const SPECS: Specs = {
  distill: {
    category: 'cost',
    type: 'boolean',
    default: false,
    repo: 'only-false',
    toggle: { on: true, off: false },
    description: {
      en: 'Distill memory and progress with Sonnet every so many messages, when idle, or at /clear',
      'zh-TW': '每隔一定則數、閒置或 /clear 時用 Sonnet 整理記憶與進度',
    },
  },
  distill_every: {
    category: 'cost',
    type: 'number',
    default: 30,
    repo: 'only-higher',
    min: 5,
    max: 200,
    description: { en: 'Distill when this many user messages have come since the last distill', 'zh-TW': '距離上次整理的使用者訊息達到這個數量時整理' },
  },
  min_context_k: {
    category: 'cost',
    type: 'number',
    default: 30,
    repo: 'only-higher',
    min: 0,
    max: 1000,
    description: { en: 'Below this many k of context, skip the every-N-messages distill', 'zh-TW': 'context 少於幾 k 不做「每幾則」的整理' },
  },
  idle_minutes: {
    category: 'cost',
    type: 'number',
    default: 10,
    repo: 'never',
    min: 0,
    max: 120,
    description: {
      en: 'Minutes of idling after the last answer before a distill; 0 means no distill when idle',
      'zh-TW': '最後一次回答後閒置幾分鐘整理一次；0 表示閒置時不整理',
    },
  },
  max_rate_used: {
    category: 'cost',
    type: 'number',
    default: 80,
    repo: 'only-lower',
    min: 0,
    max: 100,
    description: {
      en: 'Skip the automatic distill while the 5-hour or 7-day limit is used past this percent (run is not limited)',
      'zh-TW': '5 小時或 7 天額度用量超過這個百分比時，跳過自動整理（run 不受限）',
    },
  },
  promote: {
    category: 'plain',
    type: 'boolean',
    default: true,
    repo: 'any',
    description: {
      en: 'A rule confirmed in 3 sessions is proposed to you before it goes into CLAUDE.md; a procedure becomes a project skill',
      'zh-TW': '被 3 個 session 證實的規則先問你再寫進 CLAUDE.md，流程做成專案 skill',
    },
  },
  language: LANGUAGE,
}

// --- configIO: the same block in every mod (scripts/check-copies.sh) ---
function configIO($: EngineInterface): ConfigIO {
  return {
    read: async path => {
      try {
        return await $.fs.read(path)
      } catch {
        return ''
      }
    },
    write: (path, text) => $.fs.write(path, text),
    isDir: async path => (await $.fs.stat(path).catch(() => undefined))?.kind === 'dir',
    configDir: async () => (await $.env.get('CLAUDE_CONFIG_DIR')) ?? `${(await $.env.get('HOME')) ?? ''}/.claude`,
    root: () => $.session.root(),
    repoRoot: async () => (await $.session.repo())?.root,
    sessionId: () => $.session.id(),
    now: () => $.clock.now(),
    storeGet: key => $.store.get(key),
    storeSet: (key, value) => $.store.set(key, value),
  }
}
// --- end configIO ---

// Every memory and rule of this repository, one line each; no model call.
async function listText($: EngineInterface, lang: Lang): Promise<string> {
  const dir = await memoryDir($)
  const store = await loadStore($)
  const notes = notesOf(await ownFiles($, dir), store)
  const lines = listLines(notes, store.activeDays, await gonePaths($, splitLive(notes).live, await workspace($)), PROMOTE_MIN_COUNT, lang)

  return [pick(lang, { en: `Memories and rules in ${dir}:`, 'zh-TW': `${dir} 的記憶與規則：` }), ...lines.map(l => `- ${l}`)].join('\n')
}

function usage(lang: Lang): string {
  return [
    pick(lang, {
      en: `Usage: /${COMMAND} run (distill), /${COMMAND} list (every memory), /${COMMAND} status, /${COMMAND} set <key> <value> [--session|--local|--repo], /${COMMAND} unset <key>`,
      'zh-TW': `用法：/${COMMAND} run（整理）、/${COMMAND} list（列出每條記憶）、/${COMMAND} status、/${COMMAND} set <key> <value> [--session|--local|--repo]、/${COMMAND} unset <key>`,
    }),
    pick(lang, {
      en: `Automatic distill: /${COMMAND} on [duration, default 2h] turns it on for a while, /${COMMAND} off turns it off`,
      'zh-TW': `自動整理：/${COMMAND} on [時長，預設 2h] 臨時開啟、/${COMMAND} off 關閉`,
    }),
  ].join('\n')
}

export const register: Register = (on, options) => {
  // Re-read at session start, after `/project-memory set|on|off` and when a feature switched on for
  // a while runs out; `/config` changes reload the module.
  let config = configOf(resolve(SPECS, { options, user: {}, repo: {}, local: {}, session: {} }).values)
  const take = (next: Config) => {
    config = next
  }
  on('session.start', async ($, e, next) => {
    try {
      await reload($, options, take)
    } catch (error) {
      $.ui.log(`session.start: settings not read: ${String(error)}`, { to: 'debug' })
    }
    try {
      await $.command.register({
        name: COMMAND,
        description: pick(config.lang, { en: 'Distill this conversation into project memory and progress (run), or view and change settings', 'zh-TW': '整理這段對話的專案記憶與進度（run），或看、改設定' }),
        argumentHint: pick(config.lang, {
          en: 'run | list | on [duration] | off | status | set <key> <value> | unset <key>',
          'zh-TW': 'run | list | on [時長] | off | status | set <key> <value> | unset <key>',
        }),
      })
    } catch (error) {
      $.ui.log(`session.start: /${COMMAND} not registered: ${String(error)}`, { to: 'debug' })
      $.ui.toast(pick(config.lang, { en: `${COMMAND}: /${COMMAND} was not registered (${String(error)})`, 'zh-TW': `${COMMAND}：/${COMMAND} 指令沒有註冊成功（${String(error)}）` }))
    }
    if (config.isPromoteOn) {
      await $.tool.register({ name: PROMOTE_TOOL, description: PROMOTE_DESCRIPTION, inputSchema: PROMOTE_SCHEMA })
    }
    await noteActiveDay($).catch(() => undefined)

    return next(e)
  }).catch(($, e, next) => next(e))

  on('command.run', { command: COMMAND }, async ($, e) => {
    const sub = e.args.trim().split(/\s+/)[0] ?? ''
    if (sub === 'run') {
      return { text: `${await distill($, config.lang, pick(config.lang, { en: 'manual', 'zh-TW': '手動' }))}\n\n${await statusText($, config)}` }
    }
    if (sub === 'list') {
      return { text: await listText($, config.lang) }
    }
    const text = await configCommand(configIO($), COMMAND, SPECS, options, e.args, resolved => void settle($, resolved, options, take).catch(error => $.ui.log(`settle: ${String(error)}`, { to: 'debug' })))
    if (text === undefined) {
      return { text: usage(config.lang) }
    }

    return { text: sub === 'status' ? `${await statusText($, config)}\n\n${text}` : text }
  })

  // Every N prompts of the person, once the context is large enough to be worth it; and an idle
  // timer from each answer. The distill runs on a timer of its own, so the turn's dispatch is not held.
  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    try {
      if (!config.isDistillOn || e.agentId !== undefined || e.reason !== 'answer') return result
      idle?.cancel()
      idle = config.idleMs > 0 ? $.clock.after(config.idleMs, () => void onIdle($, config)) : undefined
      if (running) return result
      const mark = (await $.store.get(`distill:${await $.session.id()}`)) as Mark | undefined
      const turns = await $.session.turns()
      if (turns - (mark?.turn ?? 0) < config.every || turns < retryAt) return result
      if (((await $.session.usage()).context.tokens ?? 0) < config.minTokens) return result
      $.clock.after(0, () => void autoDistill($, config, pick(config.lang, { en: `every ${config.every} messages`, 'zh-TW': `每 ${config.every} 則` })))
    } catch (error) {
      $.ui.log(`project-memory: turn.complete: ${String(error)}`, { to: 'debug' })
    }

    return result
  }).catch(($, e, next) => next(e))

  // A /clear ends the conversation while the process goes on: take it now (the hook has about
  // 1.5 s) and distill it after. An exit leaves no time for that; the idle timer covers most of it.
  on('session.end', async ($, e, next) => {
    idle?.cancel()
    idle = undefined
    expiry?.cancel()
    ticker?.cancel()
    await update($, onUntil, () => ({})).catch(() => undefined)
    try {
      if (config.isDistillOn && e.reason === 'clear' && !running) {
        const mark = (await $.store.get(`distill:${e.sessionId}`)) as Mark | undefined
        const turns = await $.session.turns()
        if (turns - (mark?.turn ?? 0) >= END_MIN_TURNS) {
          const snap: Snapshot = { sid: e.sessionId, turns, rows: (await $.session.messages()) as readonly Row[] }
          $.clock.after(0, () => void autoDistill($, config, '/clear', snap))
        }
      }
    } catch (error) {
      $.ui.log(`project-memory: session.end: ${String(error)}`, { to: 'debug' })
    }

    return next(e)
  }).catch(($, e, next) => next(e))

  // The person's next prompt carries the latest changes, and once per session the rules and
  // procedures due to go into the repository. State changes only once the prompt went in.
  on('prompt.submit', async ($, e, next) => {
    if (e.origin.kind !== 'composer' && e.origin.kind !== 'bridge') return next(e)
    idle?.cancel()
    idle = undefined
    const context: string[] = []
    const queued = await read($, pending)
    if (queued !== null && queued.changes.length > 0) context.push(changesNote(queued.changes, queued.dir))
    const now = await $.clock.now()
    let due: ReturnType<typeof promoteItems> = []
    if (config.isPromoteOn && !(await read($, promoted))) {
      const store = await loadStore($)
      due = promoteItems(notesOf(await ownFiles($, await memoryDir($)), store), store.asked, now)
      if (due.length > 0) context.push(promoteText(due, TOOL, config.lang))
    }
    const submitted = await (context.length === 0 ? next(e) : next({ ...e, context: [...(e.context ?? []), ...context] }))
    if (submitted.drop !== undefined) return submitted
    try {
      if (queued !== null) await update($, pending, () => null)
      if (config.isPromoteOn) await update($, promoted, () => true)
      if (due.length > 0) {
        const fresh = await loadStore($)
        await $.store.set(await repoKey($), { ...fresh, asked: markAsked(fresh.asked, due, now) })
      }
      await noteActiveDay($)
    } catch (error) {
      $.ui.log(`project-memory: prompt.submit after next: ${String(error)}`, { to: 'debug' })
    }

    return submitted
  }).catch(($, e, next) => next(e))

  // While the distill is on for a while, one dim line with the time left; the bands beneath under it.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const line = onLine(COMMAND, await read($, onUntil), Math.max(await read($, now), await $.clock.now()))
    if (e.props.hasSurvey || line === '') {
      return next(e)
    }
    const below = await next(e)
    const { Box, Text } = $.ui.resolve(e)

    return (
      <Box flexDirection="column">
        <Text dimColor wrap="truncate-end">
          {line}
        </Text>
        {below}
      </Box>
    )
  })

  // Claude reports where it put a rule or procedure: record it, and drop the rule's own memory file.
  on('tool.call', { tool: TOOL }, async ($, e) => {
    const input = e as unknown as { items?: unknown }
    const dir = await memoryDir($)
    const files = await ownFiles($, dir)
    const store = await loadStore($)
    const notes = notesOf(files, store)
    const { placed, failed } = readReport(input.items, notes, config.lang)
    if (placed.length > 0) {
      const asked = { ...store.asked }
      for (const p of placed) delete asked[`${p.kind === 'rule' ? 'r' : 'p'}:${p.name}`]
      await saveNotes($, config.lang, dir, files, applyPlaced(notes, placed), asked)
    }

    return { result: promoteReport(placed, failed) }
  }).catch(($, e, next) => next(e))
}

files.hooks/config.ts:
// Layered settings, shared by every mod: the same file sits in each mod's hooks folder (a mod
// cannot import outside its own folder), and scripts/check-copies.sh keeps the copies equal.
//
// Precedence, highest first: session (`/<mod> set --session`), `.claude/cc-mod-trimtab.local.json`,
// `.claude/cc-mod-trimtab.json` (committed, held to each key's repo rule), the user layer
// (`/config` for single values, `~/.claude/cc-mod-trimtab.json` for lists), the default.
// Every file holds `{ "<mod>": { "<key>": value } }`, and may hold a `"*"` section beside them: of
// that one only `language` is read, as the value every mod shares (a mod's own section wins).
//
// A feature that spends tokens is a key with a `toggle`: `/<mod> on [feature] [duration]` sets its
// session value until a time (2h by default), `/<mod> off [feature]` takes it back.

import type { PluginOptions } from 'claude-code'

export type Value = boolean | number | string | readonly string[]

// The language of everything shown on screen. Text for the model is English whatever this is.
export type Lang = 'en' | 'zh-TW'

export type Text = Readonly<Record<Lang, string>>

export function pick(lang: Lang, text: Text): string {
  return text[lang]
}

// A description is one string (tests) or a pair.
export function say(lang: Lang, text: string | Text): string {
  return typeof text === 'string' ? text : text[lang]
}

// Where the model writes for the person (memories, handoffs), the prompt names the language.
export function writeIn(lang: Lang): string {
  return lang === 'zh-TW' ? 'Write in Traditional Chinese (zh-TW).' : 'Write in English.'
}

export type Layer = 'default' | 'user' | 'repo' | 'local' | 'session'

// What the committed repo file may do: a clone must not loosen a protection or switch on spending.
// `append` adds to the list below it; `never` leaves the key to the person's own layers.
export type RepoRule = 'any' | 'only-true' | 'only-false' | 'only-lower' | 'only-higher' | 'append' | 'never'

export type Category = 'protect' | 'cost' | 'plain'

export type KeySpec = {
  category: Category
  type: 'boolean' | 'number' | 'string' | 'list'
  default: Value
  repo: RepoRule
  description: string | Text
  min?: number
  max?: number
  // The values a string may take.
  choices?: readonly string[]
  // A feature `/<mod> on|off` switches: the value each one sets.
  toggle?: { on: Value; off: Value }
}

export type Specs = Readonly<Record<string, KeySpec>>

// The key every mod has: the language of what it shows. One value may stand for all mods in a
// settings file's `"*"` section. It is the person's own taste, so the repo file cannot set it.
export const LANGUAGE: KeySpec = {
  category: 'plain',
  type: 'string',
  default: 'en',
  repo: 'never',
  choices: ['en', 'zh-TW'],
  description: {
    en: 'Language of what this mod shows: en or zh-TW. Put {"*": {"language": "..."}} in a settings file to set it for every mod.',
    'zh-TW': '這個 mod 顯示的語言：en 或 zh-TW。在設定檔放 {"*": {"language": "..."}} 可一次設定所有 mod。',
  },
}

export type Ignored = { key: string; layer: Layer; reason: string }

export type Resolved = {
  // The language the values come to (`language`, English without it).
  lang: Lang
  values: Readonly<Record<string, Value>>
  sources: Readonly<Record<string, Layer>>
  ignored: readonly Ignored[]
  // When each key switched on by `/<mod> on` goes back, for the keys whose value it decides.
  until: Readonly<Record<string, number>>
}

export type Target = 'session' | 'local' | 'repo'

type Raw = Readonly<Record<string, unknown>>

export type Layers = {
  options: PluginOptions
  user: Raw
  repo: Raw
  local: Raw
  session: Raw
  // When the session values set by `/<mod> on` run out; the expired ones are left out already.
  until?: Readonly<Record<string, number>>
}

export const REPO_FILE = '.claude/cc-mod-trimtab.json'
export const LOCAL_FILE = '.claude/cc-mod-trimtab.local.json'
const USER_FILE = 'cc-mod-trimtab.json'
// Both keyed by session id: `$.store` is one file every session of the mod shares.
const SESSION_KEY = 'config-sessions'
const NOTICED_KEY = 'config-noticed-sessions'
// The settings files' section for what every mod shares.
const SHARED = '*'

const DEFAULT_ON_MS = 2 * 3_600_000
const MAX_ON_MS = 24 * 3_600_000
// A session's entries are dropped once nothing wrote them for this long.
const KEEP_SESSION_MS = 7 * 86_400_000

const LAYER_NAMES: Readonly<Record<Layer, Text>> = {
  default: { en: 'default', 'zh-TW': '預設' },
  user: { en: 'user', 'zh-TW': '使用者' },
  repo: { en: 'repo', 'zh-TW': 'repo' },
  local: { en: 'local', 'zh-TW': 'local' },
  session: { en: 'session', 'zh-TW': 'session' },
}

const CATEGORY_NAMES: Readonly<Record<Category, Text>> = {
  protect: { en: 'protection', 'zh-TW': '保護' },
  cost: { en: 'cost', 'zh-TW': '花費' },
  plain: { en: 'general', 'zh-TW': '一般' },
}

const RULE_NAMES: Readonly<Record<RepoRule, Text>> = {
  any: { en: 'repo may set freely', 'zh-TW': 'repo 可自由設定' },
  'only-true': { en: 'repo may only turn on', 'zh-TW': 'repo 只能開啟' },
  'only-false': { en: 'repo may only turn off', 'zh-TW': 'repo 只能關閉' },
  'only-lower': { en: 'repo may only lower', 'zh-TW': 'repo 只能調低' },
  'only-higher': { en: 'repo may only raise', 'zh-TW': 'repo 只能調高' },
  append: { en: 'repo may only add items', 'zh-TW': 'repo 只能加項目' },
  never: { en: 'repo may not set', 'zh-TW': 'repo 不能設定' },
}

function langOf(value: unknown): Lang {
  return value === 'zh-TW' ? 'zh-TW' : 'en'
}

function listOf(lang: Lang, items: readonly string[]): string {
  return items.join(lang === 'zh-TW' ? '、' : ', ')
}

// ---------- pure ----------

// A stored value of the key's type, or why it is not one.
export function parseValue(spec: KeySpec, raw: unknown, lang: Lang = 'en'): { value: Value } | { error: string } {
  switch (spec.type) {
    case 'boolean':
      return typeof raw === 'boolean' ? { value: raw } : { error: pick(lang, { en: 'must be true or false', 'zh-TW': '要是 true 或 false' }) }
    case 'number': {
      if (typeof raw !== 'number' || !Number.isFinite(raw)) {
        return { error: pick(lang, { en: 'must be a number', 'zh-TW': '要是數字' }) }
      }
      if ((spec.min !== undefined && raw < spec.min) || (spec.max !== undefined && raw > spec.max)) {
        const min = spec.min ?? '-∞'
        const max = spec.max ?? '∞'

        return { error: pick(lang, { en: `must be between ${min} and ${max}`, 'zh-TW': `要在 ${min} 到 ${max} 之間` }) }
      }

      return { value: raw }
    }
    case 'string':
      if (typeof raw !== 'string') {
        return { error: pick(lang, { en: 'must be a string', 'zh-TW': '要是字串' }) }
      }
      if (spec.choices !== undefined && !spec.choices.includes(raw)) {
        return { error: pick(lang, { en: `must be one of ${listOf(lang, spec.choices)}`, 'zh-TW': `要是 ${listOf(lang, spec.choices)} 之一` }) }
      }

      return { value: raw }
    case 'list':
      return Array.isArray(raw) && raw.every(item => typeof item === 'string')
        ? { value: raw as readonly string[] }
        : { error: pick(lang, { en: 'must be an array of strings', 'zh-TW': '要是字串陣列' }) }
  }
}

// A value typed after `/<mod> set <key>`: on/off for booleans; for lists a JSON array, or the
// whole text as one item (commas are common in a pattern, so they do not split).
export function parseInput(spec: KeySpec, text: string, lang: Lang = 'en'): { value: Value } | { error: string } {
  const t = text.trim()
  switch (spec.type) {
    case 'boolean': {
      const on = ['true', 'on', 'yes', '1'].includes(t.toLowerCase())
      const off = ['false', 'off', 'no', '0'].includes(t.toLowerCase())

      return on || off ? { value: on } : { error: pick(lang, { en: 'must be on or off', 'zh-TW': '要是 on 或 off' }) }
    }
    case 'number':
      return parseValue(spec, t === '' ? Number.NaN : Number(t), lang)
    case 'string':
      return parseValue(spec, t, lang)
    case 'list': {
      if (t.startsWith('[')) {
        try {
          return parseValue(spec, JSON.parse(t), lang)
        } catch {
          return { error: pick(lang, { en: 'not a valid JSON array', 'zh-TW': 'JSON 陣列格式不對' }) }
        }
      }

      return { value: t === '' ? [] : [t] }
    }
  }
}

function same(a: Value, b: Value): boolean {
  return JSON.stringify(a) === JSON.stringify(b)
}

// What the repo file's value comes to over the one below it, or why it is ignored.
export function applyRepoRule(spec: KeySpec, below: Value, value: Value, lang: Lang = 'en'): { value: Value } | { error: string } {
  // `never` refuses even the value below it, so `set --repo` cannot write the key at all.
  if (spec.repo !== 'never' && (same(below, value) || spec.repo === 'any')) {
    return { value }
  }
  switch (spec.repo) {
    case 'only-true':
      return value === true ? { value } : { error: pick(lang, { en: 'protection key: the repo file may only turn it on', 'zh-TW': '保護類，repo 檔案只能開啟' }) }
    case 'only-false':
      return value === false ? { value } : { error: pick(lang, { en: 'cost key: the repo file may only turn it off', 'zh-TW': '花費類，repo 檔案只能關閉' }) }
    case 'only-lower':
      return (value as number) < (below as number) ? { value } : { error: pick(lang, { en: 'the repo file may only lower it', 'zh-TW': 'repo 檔案只能調低' }) }
    case 'only-higher':
      return (value as number) > (below as number) ? { value } : { error: pick(lang, { en: 'the repo file may only raise it', 'zh-TW': 'repo 檔案只能調高' }) }
    case 'append':
      return { value: [...new Set([...(below as readonly string[]), ...(value as readonly string[])])] }
    case 'never':
      return { error: pick(lang, { en: 'the repo file may not set it; use the local file', 'zh-TW': 'repo 檔案不能設定，改用 local 檔案' }) }
  }
}

// The one key whose user layer is the settings file, single value or not: `/config` cannot hold
// a value shared by every mod.
function isFileValue(key: string, spec: KeySpec): boolean {
  return spec.type === 'list' || key === 'language'
}

function resolveKey(key: string, spec: KeySpec, layers: Layers, lang: Lang, ignored: Ignored[]): { value: Value; source: Layer } {
  let value = spec.default
  let source: Layer = 'default'
  const take = (layer: Layer, raw: unknown) => {
    if (raw === undefined) {
      return
    }
    const parsed = parseValue(spec, raw, lang)
    if ('error' in parsed) {
      ignored.push({ key, layer, reason: parsed.error })

      return
    }
    const applied = layer === 'repo' ? applyRepoRule(spec, value, parsed.value, lang) : parsed
    if ('error' in applied) {
      ignored.push({ key, layer, reason: applied.error })

      return
    }
    if (layer === 'user' && same(applied.value, spec.default)) {
      // `/config` hands over defaults filled in: the same value is no choice of the person's.
      return
    }
    value = applied.value
    source = layer
  }
  // Lists have no `/config` row; their user layer is the file.
  take('user', isFileValue(key, spec) ? layers.user[key] : layers.options[key])
  take('repo', layers.repo[key])
  take('local', layers.local[key])
  take('session', layers.session[key])

  return { value, source }
}

export function resolve(specs: Specs, layers: Layers): Resolved {
  const values: Record<string, Value> = {}
  const sources: Record<string, Layer> = {}
  const ignored: Ignored[] = []
  // The language first: the other keys' reasons are worded in it.
  const languageSpec = Object.hasOwn(specs, 'language') ? (specs.language as KeySpec) : LANGUAGE
  const lang = langOf(resolveKey('language', languageSpec, layers, 'en', []).value)
  for (const [key, spec] of Object.entries(specs)) {
    const one = resolveKey(key, spec, layers, lang, ignored)
    values[key] = one.value
    sources[key] = one.source
  }
  for (const layer of ['user', 'repo', 'local', 'session'] as const) {
    for (const key of Object.keys(layers[layer])) {
      const spec = Object.hasOwn(specs, key) ? specs[key] : undefined
      if (spec === undefined) {
        ignored.push({ key, layer, reason: pick(lang, { en: 'no such setting', 'zh-TW': '沒有這個設定' }) })
      } else if (layer === 'user' && !isFileValue(key, spec)) {
        ignored.push({
          key,
          layer,
          reason: pick(lang, { en: 'the user settings file holds lists only; use /config for a single value', 'zh-TW': '使用者設定檔只放清單，單一值用 /config' }),
        })
      }
    }
  }

  const until: Record<string, number> = {}
  for (const [key, at] of Object.entries(layers.until ?? {})) {
    if (sources[key] === 'session' && Object.hasOwn(layers.session, key)) {
      until[key] = at
    }
  }

  return { lang, values, sources, ignored, until }
}

// `2h`, `90m`, `1h30m`, or a bare number of minutes.
export function parseDuration(text: string): number | undefined {
  const t = text.trim().toLowerCase()
  const match = /^(?:(\d+)h)?(?:(\d+)m?)?$/.exec(t)
  if (t === '' || match === null || (match[1] === undefined && match[2] === undefined)) {
    return undefined
  }
  const ms = Number(match[1] ?? 0) * 3_600_000 + Number(match[2] ?? 0) * 60_000

  return ms > 0 && ms <= MAX_ON_MS ? ms : undefined
}

// `1h42m`, `37m`, `<1m`.
export function fmtLeft(ms: number): string {
  const minutes = Math.ceil(ms / 60_000)
  if (ms < 60_000) {
    return '<1m'
  }
  const h = Math.floor(minutes / 60)
  const m = minutes % 60

  return h === 0 ? `${m}m` : m === 0 ? `${h}h` : `${h}h${m}m`
}

// The band line while a feature is on for a while: `<mod> on · keep_warm 1h42m`, '' when none is.
export function onLine(mod: string, until: Readonly<Record<string, number>>, now: number): string {
  const parts = Object.entries(until)
    .filter(([, at]) => at > now)
    .map(([key, at]) => `${key} ${fmtLeft(at - now)}`)

  return parts.length === 0 ? '' : [`${mod} on`, ...parts].join(' · ')
}

// When the first of the features switched on for a while goes back.
export function nextExpiry(resolved: Resolved): number | undefined {
  const times = Object.values(resolved.until)

  return times.length === 0 ? undefined : Math.min(...times)
}

function show(value: Value): string {
  return Array.isArray(value) ? (value.length === 0 ? '[]' : value.join(', ')) : String(value)
}

export function statusText(mod: string, specs: Specs, resolved: Resolved, now = 0): string {
  const lang = resolved.lang
  const keys = Object.keys(specs)
  if (keys.length === 0) {
    return pick(lang, { en: `${mod} has no settings.`, 'zh-TW': `${mod} 沒有可調的設定。` })
  }
  const lines = [
    pick(lang, {
      en: `${mod} settings (precedence: session > local > repo > user > default)`,
      'zh-TW': `${mod} 設定（優先：session > local > repo > 使用者 > 預設）`,
    }),
  ]
  for (const key of keys) {
    const spec = specs[key] as KeySpec
    const value = resolved.values[key] as Value
    const source = resolved.sources[key] as Layer
    const at = resolved.until[key]
    const left = at === undefined ? '' : pick(lang, { en: `, on temporarily for ${fmtLeft(at - now)}`, 'zh-TW': `，臨時開啟剩 ${fmtLeft(at - now)}` })
    const kind = pick(lang, CATEGORY_NAMES[spec.category])
    const rule = pick(lang, RULE_NAMES[spec.repo])
    lines.push(`  ${key} = ${show(value)}  [${pick(lang, LAYER_NAMES[source])}${left}]  ${kind}${lang === 'zh-TW' ? '，' : ', '}${rule}`)
    lines.push(`    ${say(lang, spec.description)}`)
  }
  if (resolved.ignored.length > 0) {
    lines.push(pick(lang, { en: 'Ignored:', 'zh-TW': '已忽略：' }))
    for (const item of resolved.ignored) {
      const layer = pick(lang, LAYER_NAMES[item.layer])
      lines.push(pick(lang, { en: `  ${item.key} in ${layer}: ${item.reason}`, 'zh-TW': `  ${layer} 的 ${item.key}：${item.reason}` }))
    }
  }
  lines.push(
    pick(lang, {
      en: `Change: /${mod} set <key> <value> [--session|--local|--repo] (default --session); revert: /${mod} unset <key> [same flags]`,
      'zh-TW': `改值：/${mod} set <key> <value> [--session|--local|--repo]（預設 --session），還原：/${mod} unset <key> [同上]`,
    }),
  )
  const toggles = toggleKeys(specs)
  if (toggles.length > 0) {
    const names = listOf(lang, toggles)
    const feature = toggles.length === 1 ? '' : pick(lang, { en: ' <feature>', 'zh-TW': ' <功能>' })
    lines.push(
      pick(lang, {
        en: `Features that use the model (${names}): /${mod} on${feature} [duration, default 2h] turns one on for a while, /${mod} off${feature} turns it off`,
        'zh-TW': `用模型的功能（${names}）：/${mod} on${feature} [時長，預設 2h] 臨時開啟，/${mod} off${feature} 關閉`,
      }),
    )
  }

  return lines.join('\n')
}

function modSection(text: string, mod: string): Raw {
  if (text.trim() === '') {
    return {}
  }
  const parsed: unknown = JSON.parse(text)
  const section = typeof parsed === 'object' && parsed !== null ? (parsed as Raw)[mod] : undefined

  return typeof section === 'object' && section !== null && !Array.isArray(section) ? (section as Raw) : {}
}

// The file's text with the key set (or removed when `value` is undefined), other mods kept.
export function withSetting(text: string, mod: string, key: string, value: Value | undefined): string {
  const parsed: unknown = text.trim() === '' ? {} : JSON.parse(text)
  const all = typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed) ? { ...(parsed as Raw) } : {}
  const section = { ...modSection(text, mod) }
  if (value === undefined) {
    delete section[key]
  } else {
    section[key] = value
  }
  if (Object.keys(section).length === 0) {
    delete all[mod]
  } else {
    all[mod] = section
  }

  return `${JSON.stringify(all, null, 2)}\n`
}

export function withLocalExclude(text: string): string | undefined {
  const line = `/${LOCAL_FILE}`
  if (text.split('\n').some(l => l.trim() === line)) {
    return undefined
  }

  return `${text}${text === '' || text.endsWith('\n') ? '' : '\n'}# cc-mod-trimtab\n${line}\n`
}

const TARGET_FLAG = /(^|\s)--(session|local|repo)(?=\s|$)/g

// `<key> [value] [--session|--local|--repo]`, the flag anywhere. The value keeps its spacing.
export function parseSetArgs(args: string, lang: Lang = 'en'): { key: string; rest: string; target: Target } | { error: string } {
  const targets = [...args.matchAll(TARGET_FLAG)].map(match => match[2] as Target)
  if (targets.length > 1) {
    return { error: pick(lang, { en: 'give only one of --session, --local or --repo', 'zh-TW': '只能加一個 --session、--local 或 --repo' }) }
  }
  const text = args.replace(TARGET_FLAG, '$1').trim()
  const key = text.split(/\s+/)[0] ?? ''
  if (key === '') {
    return { error: pick(lang, { en: 'name a setting', 'zh-TW': '要指定設定名稱' }) }
  }

  return { key, rest: text.slice(key.length).trim(), target: targets[0] ?? 'session' }
}

// ---------- through the mod's I/O ----------

// What the settings need from `$`. `$` cannot cross an import, so each mod builds this in its own
// register file (the `configIO` block, kept equal across mods by scripts/check-copies.sh).
export type ConfigIO = {
  // The file's text, '' when it is missing.
  read: (path: string) => Promise<string>
  write: (path: string, text: string) => Promise<void>
  isDir: (path: string) => Promise<boolean>
  // `CLAUDE_CONFIG_DIR`, else `$HOME/.claude`.
  configDir: () => Promise<string>
  root: () => Promise<string>
  // The main working tree, whose `.git/info/exclude` covers every worktree.
  repoRoot: () => Promise<string | undefined>
  sessionId: () => Promise<string>
  now: () => Promise<number>
  storeGet: (key: string) => Promise<unknown>
  storeSet: (key: string, value: unknown) => Promise<void>
}

// What a file adds to the layers: the mod's section, with `language` from `"*"` when the section
// has none of its own, and the problems found on the way.
type Problem = { key: string; layer: Layer; reason: Text }

function readSection(text: string, path: string, mod: string, layer: Layer, broken: Problem[]): Raw {
  try {
    const own = modSection(text, mod)
    const shared = modSection(text, SHARED)
    for (const key of Object.keys(shared)) {
      if (key !== 'language') {
        broken.push({
          key: `${SHARED}.${key}`,
          layer,
          reason: { en: `only language is read from "${SHARED}"`, 'zh-TW': `"${SHARED}" 只讀 language` },
        })
      }
    }

    return shared.language === undefined || own.language !== undefined ? own : { ...own, language: shared.language }
  } catch {
    broken.push({ key: path, layer, reason: { en: 'not valid JSON; the whole file is not used', 'zh-TW': 'JSON 格式不對，整個檔案沒有採用' } })

    return {}
  }
}

type SessionEntry = { values: Raw; until?: Readonly<Record<string, number>> }
type Sessions<T> = Readonly<Record<string, T & { written: number }>>

// Every session's entry under `key`, with `id`'s replaced by `entry` and those not written for a
// week dropped.
async function writeSessions<T>(io: ConfigIO, key: string, id: string, entry: T): Promise<void> {
  const now = await io.now()
  const kept: Record<string, T & { written: number }> = {}
  for (const [other, stored] of Object.entries(((await io.storeGet(key)) ?? {}) as Sessions<T>)) {
    if (other !== id && now - stored.written < KEEP_SESSION_MS) {
      kept[other] = stored
    }
  }
  kept[id] = { ...entry, written: now }
  await io.storeSet(key, kept)
}

async function sessionEntry<T>(io: ConfigIO, key: string, id: string): Promise<T | undefined> {
  const stored = (await io.storeGet(key)) as Sessions<T> | undefined

  return stored !== undefined && Object.hasOwn(stored, id) ? stored[id] : undefined
}

// This session's values; those `/<mod> on` set left out once they ran out.
async function sessionValues(io: ConfigIO): Promise<{ values: Raw; until: Record<string, number> }> {
  const stored = await sessionEntry<SessionEntry>(io, SESSION_KEY, await io.sessionId())
  if (stored === undefined) {
    return { values: {}, until: {} }
  }
  const timed = Object.entries(stored.until ?? {})
  // Read only when needed: a mod without features to switch never asks the clock.
  const now = timed.length === 0 ? 0 : await io.now()
  const values: Record<string, unknown> = { ...stored.values }
  const until: Record<string, number> = {}
  for (const [key, at] of timed) {
    if (at > now) {
      until[key] = at
    } else {
      delete values[key]
    }
  }

  return { values, until }
}

async function writeSession(io: ConfigIO, key: string, value: Value | undefined, until: number | undefined): Promise<void> {
  const current = await sessionValues(io)
  const values: Record<string, unknown> = { ...current.values }
  const times = { ...current.until }
  delete values[key]
  delete times[key]
  if (value !== undefined) {
    values[key] = value
  }
  if (value !== undefined && until !== undefined) {
    times[key] = until
  }
  await writeSessions(io, SESSION_KEY, await io.sessionId(), { values, until: times })
}

// True the first time a feature does its work in this session, for the one notice it gets.
export async function firstUse(io: ConfigIO, key: string): Promise<boolean> {
  const sessionId = await io.sessionId()
  const keys = (await sessionEntry<{ keys: string[] }>(io, NOTICED_KEY, sessionId))?.keys ?? []
  if (keys.includes(key)) {
    return false
  }
  await writeSessions(io, NOTICED_KEY, sessionId, { keys: [...keys, key] })

  return true
}

async function filePaths(io: ConfigIO): Promise<{ user: string; repo: string; local: string }> {
  const root = (await io.root()).replace(/\/$/, '')

  return { user: `${(await io.configDir()).replace(/\/$/, '')}/${USER_FILE}`, repo: `${root}/${REPO_FILE}`, local: `${root}/${LOCAL_FILE}` }
}

async function loadLayers(io: ConfigIO, mod: string, options: PluginOptions): Promise<{ layers: Layers; broken: Problem[] }> {
  const paths = await filePaths(io)
  const broken: Problem[] = []
  const session = await sessionValues(io)
  const layers = {
    options,
    user: readSection(await io.read(paths.user), paths.user, mod, 'user', broken),
    repo: readSection(await io.read(paths.repo), paths.repo, mod, 'repo', broken),
    local: readSection(await io.read(paths.local), paths.local, mod, 'local', broken),
    session: session.values,
    until: session.until,
  }

  return { layers, broken }
}

export async function loadConfig(io: ConfigIO, mod: string, specs: Specs, options: PluginOptions): Promise<Resolved> {
  const { layers, broken } = await loadLayers(io, mod, options)
  const resolved = resolve(specs, layers)

  const problems = broken.map(item => ({ ...item, reason: pick(resolved.lang, item.reason) }))

  return { ...resolved, ignored: [...problems, ...resolved.ignored] }
}

async function writeSetting(io: ConfigIO, mod: string, key: string, value: Value | undefined, target: Target): Promise<void> {
  if (target === 'session') {
    await writeSession(io, key, value, undefined)

    return
  }
  const paths = await filePaths(io)
  const path = target === 'repo' ? paths.repo : paths.local
  await io.write(path, withSetting(await io.read(path), mod, key, value))
  if (target === 'local') {
    const repo = await io.repoRoot()
    if (repo !== undefined && (await io.isDir(`${repo}/.git`))) {
      const exclude = `${repo}/.git/info/exclude`
      const added = withLocalExclude(await io.read(exclude))
      if (added !== undefined) {
        await io.write(exclude, added)
      }
    }
  }
}

// Answers `/<mod> status|set|unset …`; undefined for any other sub-command. `reload` hands the
// mod the new values after a change.
export async function configCommand(
  io: ConfigIO,
  mod: string,
  specs: Specs,
  options: PluginOptions,
  args: string,
  reload: (resolved: Resolved) => void,
): Promise<string | undefined> {
  const sub = args.trim().split(/\s+/)[0] ?? ''
  const rest = args.trim().slice(sub.length)
  if (sub === 'status') {
    const resolved = await loadConfig(io, mod, specs, options)
    reload(resolved)

    return statusText(mod, specs, resolved, Object.keys(resolved.until).length === 0 ? 0 : await io.now())
  }
  if ((sub === 'on' || sub === 'off') && toggleKeys(specs).length > 0) {
    return switchFeature(io, mod, specs, options, sub, rest, reload)
  }
  if (sub !== 'set' && sub !== 'unset') {
    return undefined
  }
  const before = await loadLayers(io, mod, options)
  const lang = resolve(specs, before.layers).lang
  const parsed = parseSetArgs(rest, lang)
  if ('error' in parsed) {
    return parsed.error
  }
  const spec = Object.hasOwn(specs, parsed.key) ? specs[parsed.key] : undefined
  if (spec === undefined) {
    return pick(lang, {
      en: `${mod} has no setting ${parsed.key}; /${mod} status lists them all`,
      'zh-TW': `${mod} 沒有 ${parsed.key} 這個設定；/${mod} status 列出全部`,
    })
  }
  let value: Value | undefined
  if (sub === 'set') {
    const input = parseInput(spec, parsed.rest, lang)
    if ('error' in input) {
      return `${parsed.key} ${input.error}`
    }
    value = input.value
  }
  if (parsed.target === 'repo' && value !== undefined) {
    // Do not commit a value every reader would ignore.
    const { layers } = before
    const trial = resolve(specs, { ...layers, repo: { ...layers.repo, [parsed.key]: value } })
    const refused = trial.ignored.find(item => item.layer === 'repo' && item.key === parsed.key)
    if (refused !== undefined) {
      return pick(lang, { en: `Not written: ${refused.reason}`, 'zh-TW': `沒有寫入：${refused.reason}` })
    }
  }
  await writeSetting(io, mod, parsed.key, value, parsed.target)
  const resolved = await loadConfig(io, mod, specs, options)
  reload(resolved)
  const shown = show(resolved.values[parsed.key] as Value)
  const from = pick(resolved.lang, LAYER_NAMES[resolved.sources[parsed.key] as Layer])
  const now = pick(resolved.lang, { en: `${parsed.key} is now ${shown} (from ${from})`, 'zh-TW': `${parsed.key} 現在是 ${shown}（來自 ${from}）` })
  const where =
    parsed.target === 'session' ? pick(resolved.lang, { en: 'this session only', 'zh-TW': '只在這個 session' }) : parsed.target === 'repo' ? REPO_FILE : LOCAL_FILE
  const done = sub === 'set' ? pick(resolved.lang, { en: 'Set', 'zh-TW': '已設定' }) : pick(resolved.lang, { en: 'Removed', 'zh-TW': '已移除' })

  return pick(resolved.lang, { en: `${done} (${where}). ${now}`, 'zh-TW': `${done}（${where}）。${now}` })
}

export function toggleKeys(specs: Specs): string[] {
  return Object.keys(specs).filter(key => specs[key]?.toggle !== undefined)
}

// `[feature] [duration]` in either order; the feature may go when the mod has one.
export function parseOnArgs(specs: Specs, args: string, withDuration: boolean, lang: Lang = 'en'): { key: string; ms: number } | { error: string } {
  const toggles = toggleKeys(specs)
  let key: string | undefined
  let ms: number | undefined
  for (const word of args.trim().split(/\s+/).filter(w => w !== '')) {
    if (key === undefined && toggles.includes(word)) {
      key = word
      continue
    }
    const duration = withDuration && ms === undefined ? parseDuration(word) : undefined
    if (duration === undefined) {
      const names = listOf(lang, toggles)
      const hint = withDuration ? pick(lang, { en: '; a duration looks like 2h, 90m, 1h30m (24h at most)', 'zh-TW': '，時長像 2h、90m、1h30m（最多 24h）' }) : ''

      return { error: pick(lang, { en: `Cannot read "${word}": the features are ${names}${hint}`, 'zh-TW': `看不懂「${word}」：功能是 ${names}${hint}` }) }
    }
    ms = duration
  }
  if (key === undefined && toggles.length === 1) {
    key = toggles[0]
  }
  if (key === undefined) {
    return { error: pick(lang, { en: `Name a feature: ${listOf(lang, toggles)}`, 'zh-TW': `要指定功能：${listOf(lang, toggles)}` }) }
  }

  return { key, ms: ms ?? DEFAULT_ON_MS }
}

async function switchFeature(
  io: ConfigIO,
  mod: string,
  specs: Specs,
  options: PluginOptions,
  sub: 'on' | 'off',
  args: string,
  reload: (resolved: Resolved) => void,
): Promise<string> {
  const { layers } = await loadLayers(io, mod, options)
  const lang = resolve(specs, layers).lang
  const parsed = parseOnArgs(specs, args, sub === 'on', lang)
  if ('error' in parsed) {
    return parsed.error
  }
  const { key, ms } = parsed
  const toggle = (specs[key] as KeySpec).toggle as { on: Value; off: Value }
  const rest: Record<string, unknown> = { ...layers.session }
  delete rest[key]
  const below = resolve(specs, { ...layers, session: rest })
  const belowValue = below.values[key] as Value
  const isOnBelow = !same(belowValue, toggle.off)
  const now = await io.now()
  const from = pick(lang, LAYER_NAMES[below.sources[key] as Layer])
  if (sub === 'on') {
    if (isOnBelow) {
      const wasOff = Object.hasOwn(layers.session, key)
      await writeSession(io, key, undefined, undefined)
      reload(await loadConfig(io, mod, specs, options))
      const source = pick(lang, { en: `${show(belowValue)}, from ${from}`, 'zh-TW': `${show(belowValue)}，來自 ${from}` })

      return wasOff
        ? pick(lang, { en: `${key}: this session's off is cancelled, back to always on (${source})`, 'zh-TW': `${key} 取消這個 session 的關閉，回到常開（${source}）` })
        : pick(lang, { en: `${key} is already always on (${source}); no need to turn it on for a while`, 'zh-TW': `${key} 已經常開（${source}），不用臨時開啟` })
    }
    await writeSession(io, key, toggle.on, now + ms)
    reload(await loadConfig(io, mod, specs, options))
    const at = new Date(now + ms)
    const clock = `${String(at.getHours()).padStart(2, '0')}:${String(at.getMinutes()).padStart(2, '0')}`
    const off = `/${mod} off${toggleKeys(specs).length === 1 ? '' : ` ${key}`}`

    return pick(lang, {
      en: `${key} on for ${fmtLeft(ms)} (until ${clock}); it goes off by itself when that runs out or the session ends; turn off: ${off}`,
      'zh-TW': `${key} 臨時開啟 ${fmtLeft(ms)}（到 ${clock}），到期或 session 結束自動關；關閉：${off}`,
    })
  }
  // Off for the rest of the session; nothing to keep when the layers below are off already.
  await writeSession(io, key, isOnBelow ? toggle.off : undefined, undefined)
  reload(await loadConfig(io, mod, specs, options))

  return isOnBelow
    ? pick(lang, {
        en: `${key} is off for this session (${from} has it on; it comes back next session)`,
        'zh-TW': `${key} 在這個 session 關閉（${from} 設定是開啟，下個 session 恢復）`,
      })
    : pick(lang, { en: `${key} is already off`, 'zh-TW': `${key} 已關閉` })
}

