    ACTIONS_START,
    '{"op":"add_memory","type":"feedback","title":"…","how":"…","why":"…","evidence":"…","quote":"…","paths":[{"path":"src/…","anchor":"…"}]}',
    '{"op":"update_memory","id":"M3","type":"project","title":"…","how":"…","why":"…","evidence":"new evidence, may be omitted","paths":[{"path":"…","anchor":"…"}]}',
    '{"op":"confirm_memory","id":"M2","evidence":"…"}',
    '{"op":"delete_memory","id":"M7","reason":"…","superseded_by":"M4"}',
    '{"op":"add_rule","name":"…","rule":"…","applies":"…","not_applies":"…","evidence":"…","paths":[{"path":"…","anchor":"…"}]}',
    '{"op":"confirm_rule","id":"R2","evidence":"…"}',
    '{"op":"update_rule","id":"R2","rule":"…","paths":[{"path":"…","anchor":"…"}]}',
    '{"op":"delete_rule","id":"R4","reason":"…","superseded_by":"…"}',
    '{"op":"set_progress","task":"…","state":"in_progress","verified":"…","next":"…","files":["…"]}',
    '{"op":"add_procedure","name":"…","when":"…","steps":["…","…","…"],"evidence":"…"}',
    '{"op":"confirm_procedure","id":"P1","evidence":"…"}',
    '{"op":"update_procedure","id":"P1","when":"… may be omitted","steps":["…","…","…"]}',
    '{"op":"delete_procedure","id":"P3","reason":"…"}',
    ACTIONS_END,
    ...FORMAT,
  ].join('\n')
}

export const MERGE_OPS: ReadonlySet<string> = new Set(['update_memory', 'delete_memory', 'update_rule', 'delete_rule'])

// The index is over its cap: ask for merges only, no new entries.
export function mergePrompt(notes: Notes, activeDays: readonly string[], listedCount: number, cap: number, lang: Lang = 'en') {
  return [
    `You are tidying a workspace's memory. This program has ${listedCount} entries in MEMORY.md and the limit is ${cap}: merge or retire entries until there are at most ${cap}. You have no tools: output only the specified format, and a program writes the files.`,
    ...common(lang),
    '',
    ...numbered(notes, activeDays, new Map()),
    '',
    'How:',
    '- Entries that say the same thing, or can be folded into one conclusion: pick one and rewrite it with update_memory / update_rule to cover them all, and mark the others invalid with delete_memory / delete_rule, superseded_by naming the one kept.',
    '- Entries that are outdated, overturned, or derivable from the code: delete to mark them invalid (omit superseded_by).',
    '- The user\'s preferences and corrections (user, feedback) are only merged, never retired; keep type unchanged when rewriting.',
    '- Add no entries, and do not touch rules already written into the repo.',
    '',
    'Output format (copy the markers; one JSON object per line, no other text):',
    ACTIONS_START,
    '{"op":"update_memory","id":"M3","type":"project","title":"…","how":"…","why":"…","evidence":"merged M5 and M8"}',
    '{"op":"delete_memory","id":"M5","reason":"…","superseded_by":"M3"}',
    '{"op":"update_rule","id":"R2","rule":"…"}',
    '{"op":"delete_rule","id":"R4","reason":"…","superseded_by":"R2"}',
    ACTIONS_END,
    ...FORMAT,
  ].join('\n')
}

export type Rejected = { count: number; samples: string[] }
type MemoryFields = { type: MemoryType; title: string; how?: string; why?: string; evidence?: string; quote?: string; paths?: FileRef[] }
// i: the index in the list the prompt numbered; deletes do not shift it.
export type Action =
  | ({ op: 'add_memory'; evidence: string } & MemoryFields)
  | ({ op: 'update_memory'; i: number } & MemoryFields)
  | { op: 'confirm_memory'; i: number; evidence: string; quote?: string }
  | { op: 'delete_memory'; i: number; supersededBy?: string }
  | { op: 'add_rule'; name: string; rule: string; applies: string; notApplies: string; evidence: string; paths?: FileRef[] }
  | { op: 'confirm_rule'; i: number; evidence: string }
  | { op: 'update_rule'; i: number; rule: string; paths?: FileRef[] }
  | { op: 'delete_rule'; i: number; supersededBy?: string }
  | ({ op: 'set_progress' } & ProgressFields)
  | { op: 'add_procedure'; name: string; when: string; steps: string[]; evidence: string }
  | { op: 'confirm_procedure'; i: number; evidence: string }
  | { op: 'update_procedure'; i: number; when?: string; steps?: string[] }
  | { op: 'delete_procedure'; i: number }

// A count the model may append to a name ("(3 times)"): dropped, the program keeps the count. Chinese and English.
const PRESENCE_COUNT = /（\d+ 次）$|\s*\(\d+ (?:times|sessions)\)$/

// A non-empty string, newlines and runs of spaces folded, so no field spills over lines.
export const str = (v: unknown) => (typeof v === 'string' && v.trim() ? v.replace(/\s+/g, ' ').trim() : undefined)

function isQuoted(quote: string, userText: string) {
  const parts = quote.split(/…|\.\.\./).map(squash).filter(p => p.length >= 2)

  return parts.length > 0 && parts.every(p => userText.includes(p))
}

// The reasons a line is rejected are shown to the person (the run's report), so they follow the language.
const tooLong = (lang: Lang, fields: Record<string, [string | undefined, number]>) => {
  const over = Object.entries(fields)
    .filter(([, [v, max]]) => v !== undefined && [...v].length > max)
    .map(([k, [, max]]) => pick(lang, { en: `${k} is over ${max} characters`, 'zh-TW': `${k} 超過 ${max} 字` }))

  return over.length > 0 ? over.join(lang === 'zh-TW' ? '、' : ', ') : undefined
}
const missing = (lang: Lang, fields: Record<string, string | undefined>) => {
  const names = Object.entries(fields).filter(([, v]) => !v).map(([k]) => k)

  return names.length > 0 ? pick(lang, { en: `missing ${names.join(', ')}`, 'zh-TW': `缺少 ${names.join('、')}` }) : undefined
}

// An anchor worth checking: long enough, not a bare keyword, and writable between backticks.
// Otherwise undefined, and the path is kept without one.
function anchorOf(raw: unknown): string | undefined {
  const a = str(raw)
  if (a === undefined || [...a].length < ANCHOR_MIN || [...a].length > ANCHOR_MAX || a.includes('`')) return undefined

  return KEYWORDS.has(a.toLowerCase()) ? undefined : a
}

// Repository-relative paths, each a string or { path, anchor }: at most PATHS_MAX, none absolute or
// climbing out. undefined: none given.
function pathsOf(raw: unknown, lang: Lang): FileRef[] | undefined | string {
  if (raw === undefined) return undefined
  if (!Array.isArray(raw)) return pick(lang, { en: 'paths must be an array', 'zh-TW': 'paths 要是陣列' })
  const refs = raw
    .map((x): FileRef | undefined => {
      const o = x !== null && typeof x === 'object' ? (x as Record<string, unknown>) : { path: x }
      const path = str(o.path)?.replace(/^\.\//, '')
      const anchor = anchorOf(o.anchor)

      return path === undefined ? undefined : { path, ...(anchor ? { anchor } : {}) }
    })
    .filter((r): r is FileRef => r !== undefined)
  const list = refs.map(r => r.path)
  if (list.length > PATHS_MAX) return pick(lang, { en: `paths has more than ${PATHS_MAX}`, 'zh-TW': `paths 超過 ${PATHS_MAX} 個` })
  if (list.some(p => p.startsWith('/') || /^[A-Za-z]:/.test(p) || p.split('/').includes('..') || p.startsWith('~'))) return pick(lang, { en: 'paths must be relative paths in the repo', 'zh-TW': 'paths 要是 repo 裡的相對路徑' })

  return list.some(p => [...p].length > PATH_MAX || p.includes('`')) ? pick(lang, { en: `a path is over ${PATH_MAX} characters`, 'zh-TW': `paths 超過 ${PATH_MAX} 字` }) : refs
}

// One JSON line to an action, or why it is not one (kept as a rejected sample).
function toAction(o: Record<string, unknown>, notes: Notes, userText: string, lang: Lang): Action | string {
  const t = (en: string, zh: string) => pick(lang, { en, 'zh-TW': zh })
  const ref = (kind: 'M' | 'R' | 'P') => {
    const m = typeof o.id === 'string' ? /^([MRP])(\d+)$/.exec(o.id) : null
    if (!m || m[1] !== kind) return t(`id does not start with ${kind}`, `id 不是 ${kind} 開頭`)
    const i = Number(m[2]) - 1
    const len = kind === 'M' ? notes.memory.length : kind === 'R' ? notes.rules.length : notes.procedures.length

    return i >= 0 && i < len ? { i } : t(`no ${String(o.id)}`, `沒有 ${String(o.id)}`)
  }
  const paths = pathsOf(o.paths, lang)
  if (typeof paths === 'string') return paths
  const withPaths = paths === undefined ? {} : { paths }
  const memory = (hasQuote: boolean): MemoryFields | string => {
    const [title, how, why, evidence, quote] = [o.title, o.how, o.why, o.evidence, o.quote].map(str)
    if (!isMemoryType(o.type)) return t(`bad type: ${String(o.type)}`, `type 不對：${String(o.type)}`)
    const bad = missing(lang, { title }) ?? tooLong(lang, { title: [title, TITLE_MAX], how: [how, FIELD_MAX], why: [why, FIELD_MAX], evidence: [evidence, EVIDENCE_MAX], quote: [quote, QUOTE_MAX] })
    if (bad) return bad
    if (quote !== undefined && !isQuoted(quote, userText)) return t('the quote is not in the user messages', '使用者訊息裡找不到 quote')
    if (QUOTE_TYPES.includes(o.type) && quote === undefined && !hasQuote) return t(`${o.type} needs a quote`, `${o.type} 要附 quote`)

    return { type: o.type, title: title!, ...(how ? { how } : {}), ...(why ? { why } : {}), ...(evidence ? { evidence } : {}), ...(quote ? { quote } : {}), ...withPaths }
  }
  const steps = (raw: unknown) => {
    const bad = t(`steps must be ${STEP_MIN} to ${STEP_MAX_COUNT} strings`, `steps 要是 ${STEP_MIN} 到 ${STEP_MAX_COUNT} 個字串`)
    if (!Array.isArray(raw) || !raw.every(x => str(x) !== undefined)) return bad
    const list = raw.map(x => str(x)!.replace(/^\d+[.、)]\s*/, ''))
    if (list.length < STEP_MIN || list.length > STEP_MAX_COUNT) return bad

    return list.some(x => [...x].length > STEP_MAX) ? t(`a step is over ${STEP_MAX} characters`, `steps 超過 ${STEP_MAX} 字`) : list
  }
  switch (o.op) {
    case 'add_memory': {
      const m = memory(false)
      if (typeof m === 'string') return m

      return missing(lang, { evidence: m.evidence }) ?? { op: 'add_memory', ...m, evidence: m.evidence! }
    }
    case 'update_memory': {
      const r = ref('M')
      if (typeof r === 'string') return r
      const m = memory(notes.memory[r.i]!.evidence.some(e => e.includes('使用者原話') || e.includes("User's words")))

      return typeof m === 'string' ? m : { op: 'update_memory', ...r, ...m }
    }
    case 'confirm_memory': {
      const r = ref('M')
      if (typeof r === 'string') return r
      const [evidence, quote] = [o.evidence, o.quote].map(str)
      const bad = missing(lang, { evidence }) ?? tooLong(lang, { evidence: [evidence, EVIDENCE_MAX], quote: [quote, QUOTE_MAX] })
      if (bad) return bad
      if (quote !== undefined && !isQuoted(quote, userText)) return t('the quote is not in the user messages', '使用者訊息裡找不到 quote')

      return { op: 'confirm_memory', ...r, evidence: evidence!, ...(quote ? { quote } : {}) }
    }
    case 'delete_memory':
    case 'delete_rule': {
      const r = ref(o.op === 'delete_memory' ? 'M' : 'R')
      if (typeof r === 'string') return r
      const supersededBy = str(o.superseded_by)

      return missing(lang, { reason: str(o.reason) }) ?? tooLong(lang, { superseded_by: [supersededBy, TITLE_MAX] }) ?? { op: o.op, ...r, ...(supersededBy ? { supersededBy } : {}) }
    }
    case 'delete_procedure': {
      const r = ref('P')
      if (typeof r === 'string') return r

      return missing(lang, { reason: str(o.reason) }) ?? { op: 'delete_procedure', ...r }
    }
    case 'add_rule': {
      const name = str(o.name)?.replace(PRESENCE_COUNT, '').trim()
      const [rule, applies, notApplies, evidence] = [o.rule, o.applies, o.not_applies, o.evidence].map(str)

      return missing(lang, { name, rule, applies, not_applies: notApplies, evidence })
        ?? tooLong(lang, { name: [name, RULE_NAME_MAX], rule: [rule, RULE_TEXT_MAX], evidence: [evidence, EVIDENCE_MAX] })
        ?? { op: 'add_rule', name: name!, rule: rule!, applies: applies!, notApplies: notApplies!, evidence: evidence!, ...withPaths }
    }
    case 'confirm_rule':
    case 'confirm_procedure': {
      const r = ref(o.op === 'confirm_rule' ? 'R' : 'P')
      if (typeof r === 'string') return r
      const evidence = str(o.evidence)

      return missing(lang, { evidence }) ?? tooLong(lang, { evidence: [evidence, EVIDENCE_MAX] }) ?? { op: o.op, ...r, evidence: evidence! }
    }
    case 'update_rule': {
      const r = ref('R')
      if (typeof r === 'string') return r
      const rule = str(o.rule)

      return missing(lang, { rule }) ?? tooLong(lang, { rule: [rule, RULE_TEXT_MAX] }) ?? { op: 'update_rule', ...r, rule: rule!, ...withPaths }
    }
    case 'set_progress': {
      const [task, verified, next] = [o.task, o.verified, o.next].map(str)
      const state = isProgressState(o.state) ? o.state : undefined
      if (o.files !== undefined && !Array.isArray(o.files)) return t('files must be an array', 'files 要是陣列')
      const files = ((o.files as unknown[] | undefined) ?? []).map(str).filter((f): f is string => f !== undefined)
      const bad = (state ? undefined : t(`bad state: ${String(o.state)}`, `state 不對：${String(o.state)}`))
        ?? missing(lang, { task, ...(state === 'done' ? {} : { next }) })
        ?? tooLong(lang, { task: [task, PROGRESS_TASK_MAX], verified: [verified, PROGRESS_FIELD_MAX], next: [next, PROGRESS_FIELD_MAX], ...Object.fromEntries(files.map((f, i): [string, [string, number]] => [`files[${i}]`, [f, PROGRESS_FILE_MAX]])) })
        ?? (files.length > PROGRESS_FILES_MAX ? t(`files has more than ${PROGRESS_FILES_MAX}`, `files 超過 ${PROGRESS_FILES_MAX} 個`) : undefined)
      if (bad) return bad
      const p: ProgressFields = { task: task!, state: state!, ...(verified ? { verified } : {}), ...(next ? { next } : {}), files }

      return progressSize(p) > PROGRESS_TOTAL_MAX ? t(`the whole is over ${PROGRESS_TOTAL_MAX} characters`, `整份超過 ${PROGRESS_TOTAL_MAX} 字`) : { op: 'set_progress', ...p }
    }
    case 'add_procedure': {
      const name = str(o.name)?.replace(PRESENCE_COUNT, '').trim()
      const [when, evidence] = [o.when, o.evidence].map(str)
      const bad = missing(lang, { name, when, evidence }) ?? tooLong(lang, { name: [name, PROC_NAME_MAX], when: [when, FIELD_MAX], evidence: [evidence, EVIDENCE_MAX] })
      if (bad) return bad
      const list = steps(o.steps)

      return typeof list === 'string' ? list : { op: 'add_procedure', name: name!, when: when!, steps: list, evidence: evidence! }
    }
    case 'update_procedure': {
      const r = ref('P')
      if (typeof r === 'string') return r
      const when = str(o.when)
      const list = o.steps === undefined ? undefined : steps(o.steps)
      if (when === undefined && list === undefined) return t('missing when / steps', '缺少 when／steps')
      const bad = tooLong(lang, { when: [when, FIELD_MAX] })
      if (bad) return bad
      if (typeof list === 'string') return list

      return { op: 'update_procedure', ...r, ...(when ? { when } : {}), ...(list ? { steps: list } : {}) }
    }
    default:
      return t(`unknown op: ${String(o.op)}`, `不認得的 op：${String(o.op)}`)
  }
}

// A value at any depth that secret-scrub would mask (values are parsed, so escaped spellings show too).
const hasSecret = (v: unknown): boolean =>
  typeof v === 'string' ? scrub(v).labels.length > 0
    : Array.isArray(v) ? v.some(hasSecret)
      : v !== null && typeof v === 'object' ? Object.values(v).some(hasSecret)
        : false

const sampleOf = (why: string, line: string, lang: Lang) => `${why}${lang === 'zh-TW' ? '：' : ': '}${line.length > 160 ? `${line.slice(0, 100)}…${line.slice(-50)}` : line}`

// Only the lines between the markers, one JSON object each. Invalid lines are counted with up to
// three samples; a line holding a secret is dropped whole and its sample keeps no content.
// ops: the operations this request may answer with; others are rejected.
export function parseActions(text: string, notes: Notes, userText = '', ops?: ReadonlySet<string>, lang: Lang = 'en'): { actions: Action[]; rejected: Rejected } {
  const t = (en: string, zh: string) => pick(lang, { en, 'zh-TW': zh })
  const actions: Action[] = []
  const rejected: Rejected = { count: 0, samples: [] }
  const reject = (why: string, line = '', secret = false) => {
    rejected.count += 1
    if (rejected.samples.length < 3) rejected.samples.push(secret || scrub(line).labels.length > 0 ? `${why}${t(': (content not recorded)', '：（不記錄內容）')}` : sampleOf(why, line, lang))
  }
  const start = text.indexOf(ACTIONS_START)
  if (start === -1) {
    if (text.trim()) reject(t(`no ${ACTIONS_START} marker`, `沒有 ${ACTIONS_START} 標記`))

    return { actions, rejected }
  }
  let body = text.slice(start + ACTIONS_START.length)
  const end = body.indexOf(ACTIONS_END)
  if (end !== -1) body = body.slice(0, end)
  for (const line of body.split('\n').map(l => l.trim())) {
    if (!line || line.startsWith('```')) continue
    let o: unknown
    try {
      o = JSON.parse(line)
    } catch (err) {
      reject(`${t('JSON error', 'JSON 錯誤')} ${(err instanceof Error ? err.message : String(err)).slice(0, 60)}`, line)
      continue
    }
    if (!o || typeof o !== 'object' || Array.isArray(o)) {
      reject(t('not an object', '不是物件'), line)
      continue
    }
    const rec = o as Record<string, unknown>
    if (hasSecret(rec)) {
      reject(t('looks like a secret', '疑似金鑰'), '', true)
      continue
    }
    if (ops !== undefined && !ops.has(String(rec.op))) {
      reject(t(`${String(rec.op)} is not accepted this time`, `這次不接受 ${String(rec.op)}`), line)
      continue
    }
    const a = toAction(rec, notes, userText, lang)
    if (typeof a === 'string') reject(a, line)
    else actions.push(a)
  }

  return { actions, rejected }
}

export function latestProgress(actions: readonly Action[]): ProgressFields | undefined {
  const a = actions.findLast((x): x is Extract<Action, { op: 'set_progress' }> => x.op === 'set_progress')

  return a && { task: a.task, state: a.state, ...(a.verified ? { verified: a.verified } : {}), ...(a.next ? { next: a.next } : {}), files: a.files }
}

// Applies the checked actions in order to the live notes. A delete of a memory or rule marks it
// invalidated (the caller keeps the file); a procedure is removed. Numbers never shift.
// taken: the memory folder's file names, so a new file never overwrites another.
// sid: the session the conversation is from; a rule or procedure counts each session once.
export function applyActions(actions: readonly Action[], n: Notes, day: string, sid: string, taken: ReadonlySet<string>, lang: Lang = 'en'): { notes: Notes; changes: string[] } {
  const t = (en: string, zh: string) => pick(lang, { en, 'zh-TW': zh })
  // Evidence lines and `applies` join their parts with this.
  const bar = lang === 'zh-TW' ? '｜' : ' | '
  const stamp = `${day}${sid ? ` ${sid.slice(0, 8)}` : ''}`
  const names = new Set(taken)
  const newFile = (type: string, title: string) => {
    const file = fileNameFor(type, title, names)
    names.add(file)

    return file
  }
  // The date is the program's: one the model wrote at the start is dropped.
  const evidenceOf = (a: { evidence?: string; quote?: string }) => {
    const evidence = a.evidence?.replace(/^\d{4}-\d{2}-\d{2}\s*[｜|：:]?\s*/, '')

    return evidence || a.quote ? `${stamp}${bar}${[evidence, a.quote && t(`User's words: "${a.quote}"`, `使用者原話：「${a.quote}」`)].filter(Boolean).join(bar)}` : undefined
  }
  const keep = (list: string[], e: string | undefined) => (e ? [...list, e] : list).slice(-EVIDENCE_KEEP)
  const memory: Memory[] = n.memory.map(m => ({ ...m, paths: m.paths.map(p => ({ ...p })), evidence: [...m.evidence] }))
  const rules: Rule[] = n.rules.map(r => ({ ...r, paths: r.paths.map(p => ({ ...p })), sessions: [...r.sessions], evidence: [...r.evidence] }))
  const procedures = n.procedures.map(p => ({ ...p, steps: [...p.steps], sessions: [...p.sessions], evidence: [...p.evidence] })) as (Procedure | undefined)[]
  const addedMem: Memory[] = []
  const addedRules: Rule[] = []
  const addedProc: Procedure[] = []
  const changes: string[] = []
  // superseded_by names a number of this prompt or a title; numbers resolve once every update is in.
  const supersede: { item: Memory | Rule; by: string }[] = []
  const invalidate = (item: Memory | Rule, by: string | undefined) => {
    item.invalidated = day
    if (by !== undefined) supersede.push({ item, by })
  }
  for (const a of actions) {
    switch (a.op) {
      case 'add_memory': {
        if ([...memory, ...addedMem].some(m => !m.invalidated && m.title === a.title)) break
        addedMem.push({
          file: newFile(a.type, a.title),
          type: a.type,
          title: a.title,
          ...(a.how ? { how: a.how } : {}),
          ...(a.why ? { why: a.why } : {}),
          paths: a.paths ?? [],
          evidence: [evidenceOf(a)!],
          extra: [],
        })
        changes.push(t(`Added memory: [${a.type}] ${a.title}`, `新增記憶：[${a.type}] ${a.title}`))
        break
      }
      case 'update_memory': {
        const old = memory[a.i]
        if (old === undefined || old.invalidated) break
        memory[a.i] = {
          file: old.file,
          type: a.type,
          title: a.title,
          ...(a.how ? { how: a.how } : {}),
          ...(a.why ? { why: a.why } : {}),
          paths: a.paths ?? old.paths,
          evidence: keep(old.evidence, evidenceOf(a)),
          extra: old.extra,
        }
        changes.push(t(`Updated memory: [${a.type}] ${a.title}`, `更新記憶：[${a.type}] ${a.title}`))
        break
      }
      case 'confirm_memory': {
        const m = memory[a.i]
        if (m === undefined || m.invalidated) break
        m.evidence = keep(m.evidence, evidenceOf(a))
        changes.push(t(`Confirmed memory: ${m.title}`, `證實記憶：${m.title}`))
        break
      }
      case 'delete_memory': {
        const m = memory[a.i]
        if (m === undefined || m.invalidated) break
        invalidate(m, a.supersededBy)
        changes.push(t(`Memory invalidated: ${m.title}`, `記憶失效：${m.title}`))
        break
      }
      case 'add_rule': {
        if ([...rules, ...addedRules].some(r => !r.invalidated && r.name === a.name)) break
        addedRules.push({
          file: newFile('rule', a.name),
          name: a.name,
          rule: a.rule,
          applies: t(`${a.applies}${bar}Not applicable: ${a.notApplies}`, `${a.applies}${bar}不適用：${a.notApplies}`),
          count: 1,
          sessions: [sid],
          paths: a.paths ?? [],
          evidence: [`${stamp}${bar}${a.evidence}`],
          extra: [],
        })
        changes.push(t(`Added rule: ${a.name}: ${a.rule}`, `新增規則：${a.name}：${a.rule}`))
        break
      }
      case 'confirm_rule': {
        const r = rules[a.i]
        if (!r || r.invalidated) break
        const isNew = !r.sessions.includes(sid)
        if (isNew) r.count += 1
        r.sessions = withSession(r.sessions, sid)
        r.evidence = keep(r.evidence, `${stamp}${bar}${a.evidence}`)
        changes.push(
          isNew
            ? t(`Confirmed rule: ${r.name} (${r.count} sessions)`, `證實規則：${r.name}（${r.count} 個 session）`)
            : t(`Confirmed rule: ${r.name} (same session, count unchanged)`, `證實規則：${r.name}（同一個 session，不加次數）`),
        )
        break
      }
      case 'update_rule': {
        const r = rules[a.i]
        if (!r || r.invalidated || r.project !== undefined) break
        r.rule = a.rule
        if (a.paths) r.paths = a.paths
        changes.push(t(`Updated rule: ${r.name}`, `更新規則：${r.name}`))
        break
      }
      case 'delete_rule': {
        const r = rules[a.i]
        if (!r || r.invalidated || r.file === undefined) break
        invalidate(r, a.supersededBy)
        changes.push(t(`Rule invalidated: ${r.name}`, `規則失效：${r.name}`))
        break
      }
      case 'add_procedure': {
        if ([...procedures, ...addedProc].some(p => p?.name === a.name)) break
        addedProc.push({ name: a.name, when: a.when, steps: a.steps, count: 1, sessions: [sid], evidence: [`${stamp}${bar}${a.evidence}`] })
        changes.push(t(`Added procedure: ${a.name} (${a.steps.length} steps)`, `新增流程：${a.name}（${a.steps.length} 步）`))
        break
      }
      case 'confirm_procedure': {
        const p = procedures[a.i]
        if (!p) break
        const isNew = !p.sessions.includes(sid)
        if (isNew) p.count += 1
        p.sessions = withSession(p.sessions, sid)
        p.evidence = keep(p.evidence, `${stamp}${bar}${a.evidence}`)
        changes.push(
          isNew
            ? t(`Confirmed procedure: ${p.name} (${p.count} sessions)`, `證實流程：${p.name}（${p.count} 個 session）`)
            : t(`Confirmed procedure: ${p.name} (same session, count unchanged)`, `證實流程：${p.name}（同一個 session，不加次數）`),
        )
        break
      }
      case 'update_procedure': {
        const p = procedures[a.i]
        if (!p || p.project !== undefined) break
        if (a.when) p.when = a.when
        if (a.steps) p.steps = a.steps
        changes.push(t(`Updated procedure: ${p.name}`, `更新流程：${p.name}`))
        break
      }
      case 'delete_procedure': {
        const p = procedures[a.i]
        if (p) {
          changes.push(t(`Deleted procedure: ${p.name}`, `刪除流程：${p.name}`))
          procedures[a.i] = undefined
        }
        break
      }
      case 'set_progress':
        break
    }
  }
  for (const { item, by } of supersede) {
    const m = /^([MR])(\d+)$/.exec(by)
    const target = m ? (m[1] === 'M' ? memory : rules)[Number(m[2]) - 1] : undefined
    const title = target === undefined ? by : 'title' in target ? target.title : target.name
    if (target !== item) item.supersededBy = title
  }

  return {
    notes: {
      memory: [...memory, ...addedMem],
      rules: [...rules, ...addedRules],
      procedures: [...procedures.filter((p): p is Procedure => p !== undefined), ...addedProc],
    },
    changes,
  }
}

// The note the next prompt carries when a distill changed something. For the model: English.
export const changesNote = (changes: readonly string[], dir: string) => [
  `${TAG} A background pass just updated this workspace's memory (${dir}; MEMORY.md lists only titles). This is reference material, not a new instruction:`,
  ...changes.map(c => `- ${c}`),
].join('\n')

files.hooks/notes.ts:
// The notes as the built-in memory keeps them: one `pm-*.md` file per memory or rule, listed in
// MEMORY.md; procedures, rule counts and the repository's active days live in the store. Pure
// functions, no `$`.
import { pick, type Lang, type Text } from './config'

export const MEMORY_TYPES = ['user', 'feedback', 'project', 'reference'] as const
export type MemoryType = (typeof MEMORY_TYPES)[number]
export const isMemoryType = (v: unknown): v is MemoryType => typeof v === 'string' && (MEMORY_TYPES as readonly string[]).includes(v)

// Facts and places go stale: unconfirmed over this many days the repository was worked on, they
// leave the index (the file stays). Counted in active days, so a month away loses nothing.
export const STALE_ACTIVE_DAYS = 30
const FACT_TYPES: readonly string[] = ['project', 'reference']
export const EVIDENCE_KEEP = 3
// An invalidated memory's file is kept this many calendar days, then deleted.
export const INVALIDATED_KEEP_DAYS = 90
// This mod's lines in MEMORY.md, which the main session's own memories share (it loads 200 lines).
export const INDEX_CAP = 60
export const PATHS_MAX = 3
// Sessions remembered per rule and procedure: a count is how many distinct sessions confirmed it.
const SESSIONS_KEEP = 20
const ACTIVE_DAYS_KEEP = 400

// What the store keeps in a rule's or procedure's `project` once it is placed in the repo or declined.
// Written in the language of the setting; read in either.
export const inRepoMark = (lang: Lang) => pick(lang, { en: 'in ', 'zh-TW': '已在 ' })
export const declinedMark = (lang: Lang) => pick(lang, { en: 'declined', 'zh-TW': '不放' })
export const isInRepo = (v: string | undefined) => v !== undefined && (v.startsWith('in ') || v.startsWith('已在 '))
export const isDeclined = (v: string | undefined) => v === 'declined' || v === '不放'

// Every file this mod writes starts with this, so the index lines it owns are told apart.
export const FILE_PREFIX = 'pm-'
export const INDEX_FILE = 'MEMORY.md'

// A file of the repository an entry is about, relative to its root, and a string in it the entry
// relies on (a function name, a config key). Both are checked at each distill.
export type FileRef = { path: string; anchor?: string }
// A file found missing, or (anchor set) a file whose string is no longer in it.
export type Gone = FileRef

// Fields both a memory and a rule carry.
type Lifecycle = {
  paths: FileRef[]
  evidence: string[]
  // The day it was found no longer true, and what took its place.
  invalidated?: string
  supersededBy?: string
  // Lines of the body this mod does not write (someone edited the file): kept as they are.
  extra: string[]
}

export type Memory = Lifecycle & { file: string; type: MemoryType; title: string; how?: string; why?: string }

// A rule is a feedback memory file while it is the mod's own; once written into the repo the file
// goes and the record stays, so it is neither added again nor loaded twice.
export type Rule = Lifecycle & {
  file?: string
  name: string
  rule: string
  applies?: string
  count: number
  sessions: string[]
  project?: string
}

export type Procedure = { name: string; when: string; steps: string[]; count: number; sessions: string[]; evidence: string[]; project?: string }

export type Notes = { memory: Memory[]; rules: Rule[]; procedures: Procedure[] }

// What the store keeps per repository beside the files.
export type RuleMeta = { name: string; count: number; sessions?: string[]; project?: string; rule?: string }
export type PromoteAsk = { asks: number; at: number }
export type RepoStore = {
  rules: Record<string, RuleMeta>
  procedures: Procedure[]
  asked: Record<string, PromoteAsk>
  // Local dates (YYYY-MM-DD) a session ran in the repository, ascending.
  activeDays: string[]
}
export const EMPTY_STORE: RepoStore = { rules: {}, procedures: [], asked: {}, activeDays: [] }

const isRecord = (v: unknown): v is Record<string, unknown> => v !== null && typeof v === 'object' && !Array.isArray(v)

export function readStore(raw: unknown): RepoStore {
  const o = isRecord(raw) ? (raw as Partial<RepoStore>) : {}

  return {
    rules: isRecord(o.rules) ? o.rules : {},
    procedures: Array.isArray(o.procedures) ? o.procedures.map(p => ({ ...p, sessions: Array.isArray(p.sessions) ? p.sessions : [] })) : [],
    asked: isRecord(o.asked) ? o.asked : {},
    activeDays: Array.isArray(o.activeDays) ? o.activeDays.filter((d): d is string => typeof d === 'string') : [],
  }
}

export function withActiveDay(days: readonly string[], day: string): string[] | undefined {
  if (days.includes(day)) return undefined

  return [...days, day].sort().slice(-ACTIVE_DAYS_KEEP)
}

export const withSession = (sessions: readonly string[], sid: string) => [...sessions.filter(s => s !== sid), sid].slice(-SESSIONS_KEEP)

// ---------- one memory file ----------

// The labels of a memory file follow the language it was written in; reading takes both.
const LABEL: Readonly<Record<'how' | 'why' | 'applies' | 'paths', Text>> = {
  how: { en: 'How', 'zh-TW': '做法' },
  why: { en: 'Why', 'zh-TW': '理由' },
  applies: { en: 'Applies to', 'zh-TW': '適用' },
  paths: { en: 'Files', 'zh-TW': '相關檔案' },
}
const EVIDENCE_HEAD: Text = { en: '## Evidence', 'zh-TW': '## 根據' }
const FIELD_LINE = /^\*\*(做法|理由|適用|相關檔案|How|Why|Applies to|Files)[：:]\*\*\s*(.*)$/
const FIELD_KEY: Readonly<Record<string, 'how' | 'why' | 'applies' | 'paths'>> = {
  做法: 'how',
  How: 'how',
  理由: 'why',
  Why: 'why',
  適用: 'applies',
  'Applies to': 'applies',
  相關檔案: 'paths',
  Files: 'paths',
}
// Where the label ends: a full-width colon in Chinese, an ASCII one in English.
const labelOf = (lang: Lang, key: keyof typeof LABEL) => `**${pick(lang, LABEL[key])}${lang === 'zh-TW' ? '：' : ':'}**`
const oneLine = (s: string) => s.replace(/\s+/g, ' ').trim()

export type ParsedFile = {
  name: string
  description: string
  type?: MemoryType
  how?: string
  why?: string
  applies?: string
  paths: FileRef[]
  invalidated?: string
  supersededBy?: string
  evidence: string[]
  extra: string[]
}

export function parseFile(text: string): ParsedFile {
  const parsed: ParsedFile = { name: '', description: '', paths: [], evidence: [], extra: [] }
  let body = text
  const front = /^---\n([\s\S]*?)\n---\n?/.exec(text)
  if (front) {
    body = text.slice(front[0].length)
    for (const line of (front[1] ?? '').split('\n')) {
      const m = /^(\w+):\s*(.*)$/.exec(line)
      if (!m) continue
      const value = (m[2] ?? '').trim()
      if (m[1] === 'name') parsed.name = value
      if (m[1] === 'description') parsed.description = value
      if (m[1] === 'type' && isMemoryType(value)) parsed.type = value
      if (m[1] === 'invalidated' && value) parsed.invalidated = value
      if (m[1] === 'superseded_by' && value) parsed.supersededBy = value
    }
  }
  let inEvidence = false
  let sawTitle = false
  for (const raw of body.split('\n')) {
    const line = raw.trimEnd()
    if (line.startsWith('## ')) {
      inEvidence = line === EVIDENCE_HEAD['zh-TW'] || line === EVIDENCE_HEAD.en
      if (!inEvidence) parsed.extra.push(line)
      continue
    }
    if (inEvidence) {
      if (line.startsWith('- ')) parsed.evidence.push(line.slice(2).trim())
      else if (line.trim()) parsed.extra.push(line)
      continue
    }
    const field = FIELD_LINE.exec(line)
    if (field) {
      const value = (field[2] ?? '').trim()
      const key = FIELD_KEY[field[1] ?? '']
      if (key === 'paths') parsed.paths = parseRefs(value)
      else if (key !== undefined) parsed[key] = value
      continue
    }
    // The title line repeats the name; anything else someone wrote is kept.
    if (!sawTitle && line.trim() === parsed.name) {
      sawTitle = true
      continue
    }
    if (line.trim() || parsed.extra.length > 0) parsed.extra.push(line)
  }
  while (parsed.extra.length > 0 && parsed.extra.at(-1)?.trim() === '') parsed.extra.pop()

  return parsed
}

// `` `a.ts` → `anchor`, `b.ts` ``; a line someone wrote without backticks is split on commas.
const REF = /`([^`]+)`(?:\s*(?:→|->)\s*`([^`]+)`)?/g

function parseRefs(value: string): FileRef[] {
  const refs = [...value.matchAll(REF)].map(m => ({ path: m[1]!.trim(), ...(m[2]?.trim() ? { anchor: m[2].trim() } : {}) }))

  return refs.length > 0 ? refs : value.split(/\s*,\s*/).filter(Boolean).map(path => ({ path }))
}

const renderRef = (r: FileRef) => `\`${r.path}\`${r.anchor ? ` → \`${r.anchor}\`` : ''}`

// What a gone ref says, for the model and the person.
export const goneText = (g: Gone, lang: Lang) =>
  g.anchor === undefined
    ? pick(lang, { en: `${g.path} is gone`, 'zh-TW': `${g.path} 不存在` })
    : pick(lang, { en: `${g.path} no longer contains "${g.anchor}"`, 'zh-TW': `${g.path} 裡已找不到「${g.anchor}」` })

// The index line's hook and the frontmatter description: one short line.
export function describe(how?: string, why?: string, title = '') {
  return oneLine(how ?? why ?? title).slice(0, 120)
}

type FileFields = { how?: string; why?: string; applies?: string }

function renderFile(name: string, type: MemoryType, fields: FileFields, life: Lifecycle, lang: Lang) {
  return [
    '---',
    `name: ${oneLine(name)}`,
    `description: ${describe(fields.how, fields.why, name)}`,
    `type: ${type}`,
    ...(life.invalidated ? [`invalidated: ${life.invalidated}`] : []),
    ...(life.supersededBy ? [`superseded_by: ${oneLine(life.supersededBy)}`] : []),
    '---',
    '',
    name,
    '',
    ...(fields.how ? [`${labelOf(lang, 'how')} ${fields.how}`] : []),
    ...(fields.why ? [`${labelOf(lang, 'why')} ${fields.why}`] : []),
    ...(fields.applies ? [`${labelOf(lang, 'applies')} ${fields.applies}`] : []),
    ...(life.paths.length > 0 ? [`${labelOf(lang, 'paths')} ${life.paths.map(renderRef).join(', ')}`] : []),
    ...(life.extra.length > 0 ? ['', ...life.extra] : []),
    ...(life.evidence.length > 0 ? ['', pick(lang, EVIDENCE_HEAD), ...life.evidence.map(e => `- ${e}`)] : []),
    '',
  ].join('\n')
}

export const renderMemory = (m: Memory, lang: Lang = 'en') => renderFile(m.title, m.type, { how: m.how, why: m.why }, m, lang)
export const renderRule = (r: Rule, lang: Lang = 'en') => renderFile(r.name, 'feedback', { how: r.rule, applies: r.applies }, r, lang)

const lifeOf = (p: ParsedFile): Lifecycle => ({
  paths: p.paths,
  evidence: p.evidence,
  ...(p.invalidated ? { invalidated: p.invalidated } : {}),
  ...(p.supersededBy ? { supersededBy: p.supersededBy } : {}),
  extra: p.extra,
})

// The files of the memory folder, read into notes; a file the store lists as a rule is one.
export function notesOf(files: readonly { file: string; text: string }[], store: RepoStore): Notes {
  const memory: Memory[] = []
  const rules: Rule[] = []
  const seen = new Set<string>()
  for (const { file, text } of files) {
    const p = parseFile(text)
    const meta = store.rules[file]
    if (meta !== undefined) {
      seen.add(file)
      rules.push({
        file,
        name: p.name || meta.name,
        rule: p.how ?? meta.rule ?? p.description,
        ...(p.applies ? { applies: p.applies } : {}),
        count: meta.count,
        sessions: meta.sessions ?? [],
        ...(meta.project !== undefined ? { project: meta.project } : {}),
        ...lifeOf(p),
      })
      continue
    }
    if (!p.name) continue
    memory.push({ file, type: p.type ?? 'project', title: p.name, ...(p.how ? { how: p.how } : {}), ...(p.why ? { why: p.why } : {}), ...lifeOf(p) })
  }
  // Rules already written into the repo have no file; a rule whose file someone deleted is gone.
  for (const [key, meta] of Object.entries(store.rules)) {
    if (!seen.has(key) && meta.project !== undefined) {
      rules.push({ name: meta.name, rule: meta.rule ?? '', count: meta.count, sessions: meta.sessions ?? [], project: meta.project, paths: [], evidence: [], extra: [] })
    }
  }

  return { memory, rules, procedures: store.procedures.map(p => ({ ...p, steps: [...p.steps], sessions: [...p.sessions], evidence: [...p.evidence] })) }
}

// ---------- lifecycle ----------

// What the distill model works on (live) and what it never sees again (invalidated).
export function splitLive(notes: Notes): { live: Notes; dead: Notes } {
  return {
    live: { memory: notes.memory.filter(m => !m.invalidated), rules: notes.rules.filter(r => !r.invalidated), procedures: notes.procedures },
    dead: { memory: notes.memory.filter(m => m.invalidated), rules: notes.rules.filter(r => r.invalidated), procedures: [] },
  }
}

// Joins them again, dropping invalidated items past their keep: their files are then deleted.
export function joinLive(live: Notes, dead: Notes, day: string): Notes {
  const kept = (x: { invalidated?: string }) => x.invalidated === undefined || Date.parse(day) - Date.parse(x.invalidated) <= INVALIDATED_KEEP_DAYS * 86_400_000

  return {
    memory: [...live.memory, ...dead.memory].filter(kept),
    rules: [...live.rules, ...dead.rules].filter(kept),
    procedures: live.procedures,
  }
}

const lastSeen = (evidence: readonly string[]) =>
  evidence.map(e => /^(\d{4}-\d{2}-\d{2})/.exec(e)?.[1]).filter((d): d is string => d !== undefined).sort().at(-1)

// Unconfirmed over STALE_ACTIVE_DAYS of the repository's active days.
export function isArchived(m: Memory, activeDays: readonly string[]) {
  const seen = lastSeen(m.evidence)
  if (!FACT_TYPES.includes(m.type) || seen === undefined) return false

  return activeDays.filter(d => d > seen).length > STALE_ACTIVE_DAYS
}

// ---------- file names ----------

function hash(s: string) {
  let h = 0x811c9dc5
  for (const ch of s) {
    h ^= ch.codePointAt(0) ?? 0
    h = Math.imul(h, 0x01000193) >>> 0
  }

  return h.toString(16).padStart(8, '0').slice(0, 6)
}

// `pm-<type>-<ascii words of the title>-<hash>.md`: readable where the title has ASCII words, unique by the hash.
export function fileNameFor(type: string, title: string, taken: ReadonlySet<string>) {
  const words = title.toLowerCase().match(/[a-z0-9]+/g)?.join('-').slice(0, 40).replace(/-+$/, '') ?? ''
  const base = `${FILE_PREFIX}${type}-${words ? `${words}-` : ''}${hash(title)}`
  let name = `${base}.md`
  for (let i = 2; taken.has(name); i++) name = `${base}-${i}.md`

  return name
}

// ---------- MEMORY.md ----------

export type IndexEntry = { file: string; title: string; hook: string }
const ownLine = /\]\((pm-[^)]+\.md)\)/

export const indexLine = (e: IndexEntry) => `- [${oneLine(e.title)}](${e.file}) — ${oneLine(e.hook)}`

// Rewrites only the lines that link a `pm-` file: kept in place when still listed, dropped when not,
// new ones appended. Every other line stays as it is.
export function updateIndex(text: string, entries: readonly IndexEntry[]) {
  const wanted = new Map(entries.map(e => [e.file, e]))
  const placed = new Set<string>()
  const lines: string[] = []
  for (const line of text === '' ? [] : text.replace(/\n$/, '').split('\n')) {
    const file = ownLine.exec(line)?.[1]
    if (file === undefined) {
      lines.push(line)
      continue
    }
    const entry = wanted.get(file)
    if (entry !== undefined && !placed.has(file)) {
      lines.push(indexLine(entry))
      placed.add(file)
    }
  }
  for (const e of entries) {
    if (!placed.has(e.file)) lines.push(indexLine(e))
  }

  return lines.length === 0 ? '' : `${lines.join('\n')}\n`
}

type Listed = IndexEntry & { seen: string }

// Everything that belongs in the index: live memories not archived, live rules that have a file.
export function listed(notes: Notes, activeDays: readonly string[]): Listed[] {
  return [
    ...notes.memory
      .filter(m => !m.invalidated && !isArchived(m, activeDays))
      .map(m => ({ file: m.file, title: m.title, hook: describe(m.how, m.why, m.title), seen: lastSeen(m.evidence) ?? '' })),
    ...notes.rules
      .filter((r): r is Rule & { file: string } => r.file !== undefined && !r.invalidated)
      .map(r => ({ file: r.file, title: r.name, hook: describe(r.rule), seen: lastSeen(r.evidence) ?? '' })),
  ]
}

// The index lines, held to the cap: past it, the longest unconfirmed leave (their files stay).
// Merging is the distill's job; this keeps the cap when it could not.
export function indexEntries(notes: Notes, activeDays: readonly string[], cap = INDEX_CAP): IndexEntry[] {
  const all = listed(notes, activeDays)
  const keep = new Set([...all].sort((a, b) => b.seen.localeCompare(a.seen)).slice(0, cap).map(e => e.file))

  return all.filter(e => keep.has(e.file)).map(({ file, title, hook }) => ({ file, title, hook }))
}

// The store's part of the notes: rule counts, procedures, asks and active days.
export function storeOf(notes: Notes, asked: Record<string, PromoteAsk>, activeDays: string[]): RepoStore {
  const rules: Record<string, RuleMeta> = {}
  for (const r of notes.rules) {
    const key = r.file ?? `project:${r.name}`
    rules[key] = { name: r.name, count: r.count, sessions: r.sessions, ...(r.project !== undefined ? { project: r.project, rule: r.rule } : {}) }
  }

  return { rules, procedures: notes.procedures, asked, activeDays }
}

// ---------- /project-memory list ----------

// The sessions an evidence line's stamp names (`YYYY-MM-DD <sid>`); a memory keeps EVIDENCE_KEEP of them.
const sessionsOf = (evidence: readonly string[]) =>
  new Set(evidence.map(e => /^\d{4}-\d{2}-\d{2} ([0-9A-Za-z-]{1,8})(?=[｜|\s]|$)/.exec(e)?.[1]).filter((s): s is string => s !== undefined)).size

type ListItem = { type: string; title: string; sessions: number; seen: string; status: string[]; isDead: boolean }

// One plain line per memory and rule that has a file: type, title, sessions confirmed in, last
// confirmed, and where it stands. gone: a file's refs no longer found. promoteMin:
// the sessions a rule needs before it is asked into CLAUDE.md.
export function listLines(notes: Notes, activeDays: readonly string[], gone: ReadonlyMap<string, Gone[]>, promoteMin: number, lang: Lang, cap = INDEX_CAP): string[] {
  const t = (en: string, zh: string) => pick(lang, { en, 'zh-TW': zh })
  const inIndex = new Set(indexEntries(notes, activeDays, cap).map(e => e.file))
  const statusOf = (file: string, x: { invalidated?: string }, archived: boolean) => {
    if (x.invalidated) return [t(`invalidated ${x.invalidated}`, `失效 ${x.invalidated}`)]
    const status = [archived ? t('stale', '已過期') : inIndex.has(file) ? t('listed', '列在目錄') : t(`not listed (over ${cap})`, `未列（超過 ${cap} 條）`)]
    const missing = gone.get(file)
    if (missing !== undefined) status.push(...missing.map(g => goneText(g, lang)))

    return status
  }
  const items: ListItem[] = [
    ...notes.memory.map(m => ({
      type: m.type,
      title: m.title,
      sessions: sessionsOf(m.evidence),
      seen: lastSeen(m.evidence) ?? '',
      status: statusOf(m.file, m, isArchived(m, activeDays)),
      isDead: m.invalidated !== undefined,
    })),
    ...notes.rules
      .filter((r): r is Rule & { file: string } => r.file !== undefined)
      .map(r => ({
        type: t('rule', '規則'),
        title: r.name,
        sessions: r.count,
        seen: lastSeen(r.evidence) ?? '',
        status: [...statusOf(r.file, r, false), ...(!r.invalidated && r.project === undefined && r.count >= promoteMin ? [t('waiting to go into CLAUDE.md', '等待寫進 CLAUDE.md')] : [])],
        isDead: r.invalidated !== undefined,
      })),
  ].sort((a, b) => Number(a.isDead) - Number(b.isDead) || b.seen.localeCompare(a.seen))
  if (items.length === 0) return [t('No memories yet.', '還沒有記憶。')]
  const sep = lang === 'zh-TW' ? '、' : '; '

  return items.map(i =>
    `[${i.type}] ${oneLine(i.title)} · ${t(`${i.sessions} session(s)`, `${i.sessions} 個 session`)} · ${i.seen || t('never confirmed', '未證實')} · ${i.status.join(sep)}`)
}

files.hooks/progress.ts:
// Where the work stands, as `.claude/progress.md` in the repository: written by each distill that
// saw real progress, overwritten by session-keeper's handoff, read only by session-keeper. Kept out
// of git through `.git/info/exclude`. Pure functions, no `$`.
import { pick, type Lang, type Text } from './config'

export const PROGRESS_FILE = '.claude/progress.md'
export const PROGRESS_STATES = ['done', 'in_progress', 'blocked'] as const
export type ProgressState = (typeof PROGRESS_STATES)[number]
export const isProgressState = (v: unknown): v is ProgressState => typeof v === 'string' && (PROGRESS_STATES as readonly string[]).includes(v)
const STATE_LABEL: Record<ProgressState, Text> = {
  done: { en: 'done', 'zh-TW': '完成' },
  in_progress: { en: 'in progress', 'zh-TW': '進行中' },
  blocked: { en: 'blocked', 'zh-TW': '卡住' },
}

// Limits per field and in all (any character counts one).
export const PROGRESS_TASK_MAX = 80
export const PROGRESS_FIELD_MAX = 120
export const PROGRESS_FILES_MAX = 5
export const PROGRESS_FILE_MAX = 80
export const PROGRESS_TOTAL_MAX = 600

export type ProgressFields = { task: string; state: ProgressState; verified?: string; next?: string; files: string[] }
export type Progress = ProgressFields & { session: string; at: number }

export const progressSize = (p: ProgressFields) => [p.task, p.verified, p.next, ...p.files].reduce((n, s) => n + [...(s ?? '')].length, 0)

// at: written by the caller as local time, so the file reads like the rest of the notes.
export function renderProgress(p: Progress, stamp: string, lang: Lang = 'en') {
  return [
    '---',
    'source: project-memory',
    `session: ${p.session}`,
    `updated: ${new Date(p.at).toISOString()}`,
    `state: ${p.state}`,
    '---',
    '',
    pick(lang, { en: `# Progress (${stamp})`, 'zh-TW': `# 進度（${stamp}）` }),
    '',
    pick(lang, { en: `- Task: ${p.task}`, 'zh-TW': `- 任務：${p.task}` }),
    pick(lang, { en: `- State: ${pick(lang, STATE_LABEL[p.state])}`, 'zh-TW': `- 狀態：${pick(lang, STATE_LABEL[p.state])}` }),
    ...(p.verified ? [pick(lang, { en: `- Last passing check: ${p.verified}`, 'zh-TW': `- 最後通過的檢查：${p.verified}` })] : []),
    ...(p.next ? [pick(lang, { en: `- Next step: ${p.next}`, 'zh-TW': `- 下一步：${p.next}` })] : []),
    ...(p.files.length > 0 ? [pick(lang, { en: '- Key files:', 'zh-TW': '- 關鍵檔案：' }), ...p.files.map(f => `  - ${f}`)] : []),
    '',
  ].join('\n')
}

// The current progress for the distill prompt: the file's body, or none. A handoff summary written
// by session-keeper is passed the same way, so the model continues from it. For the model: English.
export function progressForPrompt(text: string) {
  const body = text.replace(/^---\n[\s\S]*?\n---\n?/, '').trim()

  return body === '' ? '(none)' : body.replace(/\n+/g, ' ／ ').slice(0, 1200)
}

// `.git/info/exclude` with the progress file listed once.
export function withExclude(text: string) {
  const line = `/${PROGRESS_FILE}`
  if (text.split('\n').some(l => l.trim() === line)) return undefined

  return `${text}${text === '' || text.endsWith('\n') ? '' : '\n'}# project-memory\n${line}\n`
}

files.hooks/promote.ts:
// Rules and procedures confirmed often enough go into the repository: which ones to hand Claude,
// the text that asks, and what Claude reports back. Adapted from ctx-handoff-mod's promote.ts (MIT).
// Pure functions, no `$`. What goes to the model (the ask, the tool and its reply) is English.
import { writeIn, type Lang } from './config'
import { str } from './distill'
import { declinedMark, inRepoMark, isDeclined } from './notes'
import type { Notes, PromoteAsk } from './notes'
import { TAG } from './transcript'

export const PROMOTE_MIN_COUNT = 3
const PROMOTE_MAX_ASKS = 2
const PROMOTE_COOLDOWN_MS = 6 * 60 * 60_000
const PROMOTE_ITEMS = 3

export const PROMOTE_TOOL = 'mark_in_project'
export const PROMOTE_DESCRIPTION =
  'Record where a project-memory rule or procedure now lives in this repo (after the user agreed and you wrote it into CLAUDE.md, ' +
  'or after you made the project skill), or that the user declined. project-memory then removes its own memory file for that rule and stops asking.'
export const PROMOTE_SCHEMA = {
  type: 'object',
  properties: {
    items: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          rule: { type: 'string', description: 'The rule name, copied exactly from the quoted text' },
          procedure: { type: 'string', description: 'The procedure name, copied exactly from the quoted text' },
          where: { type: 'string', description: 'Where in the repo it was put, e.g. CLAUDE.md or .claude/skills/release/SKILL.md' },
          declined: { type: 'boolean', description: 'The user does not want it in the repo' },
        },
      },
    },
  },
  required: ['items'],
} as const

export type PromoteItem = { key: string; line: string }

// Due now: asked at most twice, six hours apart, three at a time.
export function promoteItems(notes: Notes, asked: Record<string, PromoteAsk>, now: number): PromoteItem[] {
  const ready = (key: string) => {
    const a = asked[key]

    return !a || (a.asks < PROMOTE_MAX_ASKS && now - a.at >= PROMOTE_COOLDOWN_MS)
  }
  const rules = notes.rules
    .filter(r => r.count >= PROMOTE_MIN_COUNT && r.project === undefined && !r.invalidated)
    .sort((a, b) => b.count - a.count)
    .map(r => ({ key: `r:${r.name}`, line: `- Rule "${r.name}" (confirmed in ${r.count} sessions): ${r.rule}` }))
  const procedures = notes.procedures
    .filter(p => p.count >= PROMOTE_MIN_COUNT && p.project === undefined)
    .sort((a, b) => b.count - a.count)
    .map(p => ({ key: `p:${p.name}`, line: `- Procedure "${p.name}" (confirmed in ${p.count} sessions): ${p.when} | steps: ${p.steps.map((s, i) => `${i + 1}. ${s}`).join('; ')}` }))

  return [...rules, ...procedures].filter(c => ready(c.key)).slice(0, PROMOTE_ITEMS)
}

export function markAsked(asked: Record<string, PromoteAsk>, items: readonly { key: string }[], now: number) {
  const next = { ...asked }
  for (const c of items) next[c.key] = { asks: (asked[c.key]?.asks ?? 0) + 1, at: now }

  return next
}

// CLAUDE.md is the person's to write: rules are proposed and wait for a yes. A procedure becomes a
// skill of its own, which the person reviews as a new file, so it is written straight away.
export const promoteText = (items: readonly PromoteItem[], tool: string, lang: Lang = 'en') => {
  const hasRules = items.some(c => c.key.startsWith('r:'))
  const hasProcedures = items.some(c => c.key.startsWith('p:'))

  return [
    `${TAG} The practices below were confirmed in several conversations but are not in this repo yet. Finish what the user asked for this time first, then handle them at the end of this turn's reply; if the user said they are dealing with an urgent problem, put it off to a later turn.`,
    ...[
      ...(hasRules
        ? ['Rules go into CLAUDE.md, but CLAUDE.md is the user\'s to decide, so do not edit it directly: read what is there first, and if the same rule exists, only report where it is; otherwise list at the end of your reply the text to add and the file to put it in (CLAUDE.md at the repo root or under .claude/, following the project\'s convention) and ask the user whether to add it. Write it only after the user agrees; if they do not, leave it unchanged.']
        : []),
      ...(hasProcedures
        ? ['Procedures become project skills: .claude/skills/<kebab-case name>/SKILL.md, with frontmatter name (the same as the folder) and description (one sentence on when to use it), and the steps in order in the body, keeping commands and file names. If a skill or document already covers the same procedure, extend it and report where, instead of starting another. When done, tell the user at the end of your reply, and delete it if the user says no.']
        : []),
      `${writeIn(lang)} When adding to a file that is already written in another language, match that file instead.`,
      'Only edit files; do not commit or push.',
      `After writing, call ${tool} to report where each one went (rule for a rule, procedure for a procedure, where for the file location); when the user says no, mark it declined with ${tool}. Do not call it while the user has not answered.`,
    ].map((l, i) => `${i + 1}. ${l}`),
    '',
    ...items.map(c => c.line),
  ].join('\n')
}

export type Placed = { kind: 'rule' | 'procedure'; name: string; value: string }

// Claude's report, checked against the notes: what to record, and what could not be.
export function readReport(raw: unknown, notes: Notes, lang: Lang = 'en'): { placed: Placed[]; failed: string[] } {
  const items = Array.isArray(raw) ? (raw as Record<string, unknown>[]) : []
  const placed: Placed[] = []
  const failed: string[] = []
  for (const it of items) {
    const declined = it.declined === true
    const where = str(it.where)
    const kind = typeof it.rule === 'string' ? 'rule' : typeof it.procedure === 'string' ? 'procedure' : undefined
    const name = kind === 'rule' ? String(it.rule).trim() : kind === 'procedure' ? String(it.procedure).trim() : ''
    const label = kind === 'rule' ? `rule "${name}"` : kind === 'procedure' ? `procedure "${name}"` : JSON.stringify(it)
    if (kind === undefined) {
      failed.push(`${label}: needs rule or procedure`)
      continue
    }
    if (!declined && !where) {
      failed.push(`${label}: missing where`)
      continue
    }
    const list: readonly { name: string }[] = kind === 'rule' ? notes.rules.filter(r => !r.invalidated) : notes.procedures
    if (!list.some(x => x.name === name)) {
      failed.push(`${label}: not in the notes`)
      continue
    }
    placed.push({ kind, name, value: declined ? declinedMark(lang) : `${inRepoMark(lang)}${where}` })
  }

  return { placed, failed }
}

// The notes with the report applied: a placed rule loses its file (the caller deletes it).
export function applyPlaced(notes: Notes, placed: readonly Placed[]): Notes {
  const of = (kind: Placed['kind'], name: string) => placed.find(p => p.kind === kind && p.name === name)?.value

  return {
    memory: notes.memory,
    rules: notes.rules.map(r => {
      const value = of('rule', r.name)
      if (value === undefined) return r
      // Declined: the rule stays a memory; written into the repo: its own file goes.
      if (isDeclined(value)) return { ...r, project: value }
      const { file: _file, ...rest } = r

      return { ...rest, project: value }
    }),
    procedures: notes.procedures.map(p => {
      const value = of('procedure', p.name)

      return value === undefined ? p : { ...p, project: value }
    }),
  }
}

export const promoteReport = (placed: readonly Placed[], failed: readonly string[]) => [
  ...(placed.length > 0 ? ['Recorded:', ...placed.map(p => `${p.kind} "${p.name}": ${p.value}`)] : []),
  ...(failed.length > 0 ? ['Not recorded:', ...failed] : []),
].join('\n') || 'No items received'

files.hooks/transcript.ts:
// The conversation as plain text for the distill model: tool inputs and results clipped, secrets
// masked with secret-scrub's rules, only what came after the last distill. Pure functions, no `$`.
// It is read by the model only, so its labels are English.
import { scrub } from './scrub'

const TRANSCRIPT_MAX_CHARS = 300_000
const TOOL_INPUT_CHARS = 300
const TOOL_RESULT_CHARS = 500

// Every message this mod adds to the conversation starts with it: context for the model, never evidence.
export const TAG = '[project-memory]'

export type Row = {
  role: 'user' | 'assistant'
  text: string
  toolUses: readonly { tool: string; input: Record<string, unknown>; text?: string; isError?: true }[]
}

// The start of a person's message, kept as where the next distill begins.
export const anchorOf = (text: string) => text.replace(/\s+/g, ' ').trim().slice(0, 30)
export const clip = (s: string, n: number) => (s.length > n ? `${s.slice(0, n)}… (truncated, was ${s.length} characters)` : s)

// Rows after the latest user message that opens with the anchor; all rows when there is none.
export function transcriptOf(rows: readonly Row[], anchor: string | undefined) {
  let start = 0
  let found = false
  if (anchor) {
    for (let i = rows.length - 1; i >= 0; i--) {
      const r = rows[i]
      if (r?.role === 'user' && r.text.replace(/\s+/g, ' ').includes(anchor)) {
        start = i + 1
        found = true
        break
      }
    }
  }
  const lines: string[] = []
  for (const r of rows.slice(start)) {
    if (r.role === 'user') {
      if (r.text.trim()) lines.push(`[User] ${r.text.trim()}`)
      continue
    }
    if (r.text.trim()) lines.push(`[Assistant] ${r.text.trim()}`)
    for (const u of r.toolUses) {
      const out = u.text === undefined ? '' : ` → ${u.isError ? 'error: ' : ''}${clip(u.text.replace(/\s+/g, ' '), TOOL_RESULT_CHARS)}`
      lines.push(`  [tool ${u.tool}] ${clip(JSON.stringify(u.input), TOOL_INPUT_CHARS)}${out}`)
    }
  }
  let text = scrub(lines.join('\n')).text
  if (text.length > TRANSCRIPT_MAX_CHARS) text = `(first ${text.length - TRANSCRIPT_MAX_CHARS} characters omitted)\n${text.slice(-TRANSCRIPT_MAX_CHARS)}`

  return { text, found }
}

// The person's own words, spaces removed, to check a quoted memory against; this mod's own
// messages do not count.
export const squash = (s: string) => s.replace(/\s+/g, '')
export const userTextOf = (rows: readonly Row[]) =>
  squash(rows.filter(r => r.role === 'user' && !r.text.startsWith(TAG)).map(r => r.text).join('\n'))

// The last person message's anchor: where this distill ends and the next begins.
export function lastAnchor(rows: readonly Row[]) {
  for (let i = rows.length - 1; i >= 0; i--) {
    const r = rows[i]
    if (r?.role === 'user' && r.text.trim() && !r.text.startsWith(TAG)) return anchorOf(r.text)
  }

  return undefined
}

files.hooks/scrub.ts:
// Finds secrets in free text and replaces their values with a placeholder, keeping the
// surrounding name (`token=`, `Authorization: Bearer`, `API_KEY=`) so the text still reads.

export const MASK = '‹redacted›'

// A prompt containing the marker is sent as typed (the marker itself removed), for the rare
// case where Claude really needs the secret. The marker is the setting `bypass_marker`.
export function bypassPattern(marker: string): RegExp {
  return new RegExp(`(^|\\s)${marker.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?!\\w)`)
}

export const BYPASS = bypassPattern('#noscrub')

// The settings `custom_rules` (masked whole) and `allow` (left as typed) compiled.
export type ScrubOptions = { rules?: readonly RegExp[]; allow?: readonly RegExp[] }

// Compiles each pattern, global for masking or not for testing; `bad` lists the ones that do not compile.
export function compilePatterns(patterns: readonly string[], flags: string): { patterns: RegExp[]; bad: string[] } {
  const compiled: RegExp[] = []
  const bad: string[] = []
  for (const pattern of patterns) {
    try {
      compiled.push(new RegExp(pattern, flags))
    } catch {
      bad.push(pattern)
    }
  }

  return { patterns: compiled, bad }
}

type Rule = {
  label: string
  pattern: RegExp
  // Index of the capture group holding the secret; 0 replaces the whole match.
  group: number
}

// Values shorter than this in name=value forms are treated as examples (`token=xxx`).
const MIN_VALUE = 8

const RULES: Rule[] = [
  {
    label: 'private key',
    pattern: /-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----/g,
    group: 0,
  },
  { label: 'Anthropic key', pattern: /\bsk-ant-[A-Za-z0-9_-]{20,}/g, group: 0 },
  { label: 'API key', pattern: /\bsk-(?:proj-)?[A-Za-z0-9_-]{20,}/g, group: 0 },
  { label: 'GitHub token', pattern: /\b(?:gh[pousr]_[A-Za-z0-9]{30,}|github_pat_[A-Za-z0-9_]{30,})/g, group: 0 },
  { label: 'Slack token', pattern: /\bxox[abprs]-[A-Za-z0-9-]{10,}/g, group: 0 },
  { label: 'AWS key', pattern: /\bAKIA[0-9A-Z]{16}\b/g, group: 0 },
  { label: 'Google key', pattern: /\bAIza[0-9A-Za-z_-]{35}\b/g, group: 0 },
  {
    label: 'JWT',
    pattern: /\beyJ[A-Za-z0-9_-]{8,}\.eyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}/g,
    group: 0,
  },
  {
    label: 'Bearer token',
    pattern: /\b(?:Bearer|Basic)\s+([A-Za-z0-9._~+\/=-]{8,})/g,
    group: 1,
  },
  {
    label: 'URL credential',
    pattern: /\b[a-z][a-z0-9+.-]*:\/\/[^\s:@\/]+:([^\s@\/]{4,})@/gi,
    group: 1,
  },
  {
    label: 'query token',
    pattern:
      /[?&](?:access_token|refresh_token|id_token|token|api_?key|apikey|key|secret|client_secret|password|passwd|pwd|auth|sig|signature)=([^&#\s"'`<>]+)/gi,
    group: 1,
  },
  {
    // `token=…` typed in prose. Only unmistakable names: `key=`, `auth=` and the like are common in
    // code, and `${VAR}` / `{var}` placeholders are no secret.
    label: 'token',
    pattern:
      /(?<![\w.\/-])(?:access_token|refresh_token|id_token|token|api_?key|secret|client_secret|password|passwd)=(?![{$<])([^&#\s"'`<>()]+)/gi,
    group: 1,
  },
  {
    label: 'env secret',
    pattern:
      /^\s*(?:export\s+)?[A-Z0-9_]*(?:SECRET|TOKEN|API_?KEY|ACCESS_KEY|PASSWORD|PASSWD|PRIVATE_KEY|CREDENTIALS?)[A-Z0-9_]*\s*[=:]\s*["']?([^\s"'#]+)/gm,
    group: 1,
  },
]

export type Scrubbed = { text: string; labels: string[] }

export function scrub(input: string, options: ScrubOptions = {}): Scrubbed {
  const labels: string[] = []
  let text = input
  const allow = options.allow ?? []
  const custom = (options.rules ?? []).map(pattern => ({ label: 'custom rule', pattern, group: 0 }))

  for (const rule of [...RULES, ...custom]) {
    text = text.replace(rule.pattern, (match: string, ...rest: unknown[]) => {
      if (match.includes(MASK)) {
        return match
      }
      if (rule.group === 0) {
        if (allow.some(pattern => pattern.test(match))) {
          return match
        }
        labels.push(rule.label)

        return MASK
      }
      const value = rest[rule.group - 1]
      if (typeof value !== 'string' || value.length < MIN_VALUE || value.includes(MASK) || allow.some(pattern => pattern.test(value))) {
        return match
      }
      labels.push(rule.label)
      const at = match.lastIndexOf(value)

      return match.slice(0, at) + MASK + match.slice(at + value.length)
    })
  }

  return { text, labels }
}

// Counts each label once with its number: "query token ×2, JWT".
export function summarize(labels: string[]): string {
  const counts = new Map<string, number>()
  for (const label of labels) {
    counts.set(label, (counts.get(label) ?? 0) + 1)
  }

  return [...counts].map(([label, n]) => (n > 1 ? `${label} ×${n}` : label)).join(', ')
}

